quests[28604] = { id = 28604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deception and Trickery", description = "As long as I am by your side the enemy will think of you as one of their own. Your newfound humanity, however, will not allow you to be reckless. If you draw attention to yourself the dwarves will grow suspicious and likely attack!\n\nWith that said, I have a plan. Take this barrel of poisoned water and use it to sate the thirst of the tired Stormpike trainees. Once they drink from it they will become deathly ill, eventually succumbing to the poison.", sourceObjective = "Use the Barrel of Water to Poison 30 Stormpike Trainees.", progress = "Deception and trickery - these are your tools!", completion = "They won't die immediately, but they WILL die! When they finally piece together who was responsible for the deaths of their soldiers, you will be long gone - a phantom of death!", sourceObjectiveStatus = "unverified-source-field" }
quests[28605] = { id = 28605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Domination", description = "<Melisara's thoughts intermingle with your thoughts.>\n\nThe last task will be an assault against the siege technicians of Gavin's Naze, located west of the Headland. Venture to the final finger and lay waste to the dwarf and gnome engineers that build and fortify the Stormpike machines of war. Be sure to plant Cromush's final pocket-nuke as well.", sourceObjective = "Kill 10 Stormpike Engineers.", completion = "With the Stormpike forces maimed, the time has come for detonation!", sourceObjectiveStatus = "unverified-source-field" }
quests[28606] = { id = 28606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keys to the Hot Rod" }
quests[28607] = { id = 28607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keys to the Hot Rod" }
quests[28608] = { id = 28608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Grave", description = "I'm pleased to see that you're up and walking around, {name}.  You've held up nicely, especially after being dead for so long!\n\nOthers weren't as lucky.  If you wouldn't mind, I need you to fetch my embalming fluid and some twine to stitch up these bodies.  You'll find both in the Shadow Grave, the building just behind me.\n\nHere, Darnell will join you.  He knows the way.", sourceObjective = "Obtain the Thick Embalming Fluid and the Corpse-Stitching Twine from the Shadow Grave in Deathknell.", progress = "You will find the items within the Shadow Grave.  I believe I left them on my work table.", completion = "Exactly what I needed.  You'll be an asset to the Forsaken, {name}.\n\nYou know, word has it that you were quite the {class} in your previous life.  Perhaps I should assign you to a more exciting task.", sourceObjectiveStatus = "unverified-source-field" }
quests[28609] = { id = 28609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammer Time", description = "The three of us have been arguing for weeks over whose weapons are superior.\n\nI won't let anyone tell me my maces are second best. Kilram's axes and Seril's swords could never match the pure strength of my craft.\n\nI'm tired of arguing. It's time to show those two I'm right with a demonstration. If you would, dear, head outside and tell Deez Rocksnitch that I need the biggest boulder he can find!", sourceObjective = "Speak with Deez Rocksnitch.", completion = "Lilith wants a boulder moved inside the observatory, eh? That's my business: consolidated materials. I usually don't get individual buyers, but hey, I won't ask questions.", sourceObjectiveStatus = "unverified-source-field" }
quests[28610] = { id = 28610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rubble Trouble", description = "If you want to get a boulder in there, you can use my own patented Boulder-in-a-Box! Normally I'd just sell you one up front, but I'm fresh out of materials.\n\nEarth elementals have been popping up on the peak directly south of town. They're a good source of rubble. If you bring me back a good amount, I'll pay you for the restock, and I'll throw in a Boulder-in-a-Box absolutely free!", sourceObjective = "Collect 6 Prime Rubble Chunks from Frostshard Rumblers.", progress = "You got that rubble?", completion = "Looks like a good amount! Here's your pay, as promised...", sourceObjectiveStatus = "unverified-source-field" }
quests[28611] = { id = 28611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defilers' Ritual", description = "Ah, I can already see more clearly, {name}.\n\nWe are right to be wary of the evil Neferset.  I can already sense that they're behind the forces that corrupt the river.\n\nGo underwater once more and find the Murkdeep Cavern.  You will find the Neferset are performing a foul ritual of corruption.\n\nStop them so the river is cleansed once again.", sourceObjective = "Stop the Neferset Ritual at the Murkdeep Cavern.", progress = "Is it done, {name}?", completion = "The waters of the river are nearly cleansed.  Our prophetic visions will soon return.", sourceObjectiveStatus = "unverified-source-field" }
quests[28612] = { id = 28612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harrison Jones and the Temple of Uldum", description = "After all we've been through, it looks like everything's actually coming together!\n\nWe're just steps away from the coffer... I've researched the codes to reveal it... Schnottz thinks we're dead....\n\nYou know, we might just pull this off after all!", sourceObjective = "Recover the Coffer of Promise.", completion = "Lucky fer you, this ol' dwarf's still got a few tricks up his sleeve!\n\nHeehee! ...shoulda seen tha look on yer faces!", sourceObjectiveStatus = "unverified-source-field" }
quests[28613] = { id = 28613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See You on the Other Side!", description = "Alright, {name}. We've bought ourselves a little breathing room, but there's no time to lose.\n\nFollow me!", sourceObjective = "Speak to Harrison Jones at the top of Maker's Ascent in Uldum.", completion = "So far, so good...", sourceObjectiveStatus = "unverified-source-field" }
quests[28614] = { id = 28614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bearzerker", description = "High Chieftain Winterfall's absence has done little to quell the rage of the Winterfall. In his absence, their greatest warrior has rose to a position of terrible power.\n\nGrolnar the Berserk lurks in the cave at the top of Winterfall Village, gorged on enough corrupt firewater to kill ten lesser furbolgs.\n\nHe has become a bloated and horrible beast! Our warriors have been unable to face him... do you have the strength to defeat him, {class}?", sourceObjective = "Slay Grolnar the Berserk.", progress = "Has Grolnar fallen?", completion = "Your actions prove yourself a mighty warrior to me and all the Timbermaw!\n\nLet us hope the Winterfall will be defeated for good now...", sourceObjectiveStatus = "unverified-source-field" }
quests[28615] = { id = 28615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning the Earth", description = "Despite their corruption and madness, the Winterfall barely cling to their shamanic powers. It disturbs me to see the power of the elements used by them to harm my tribe and other innocents.\n\nWe will turn their totems against them! Take my own totem with you into Winterfall Village. Use its powers on the Winterfall's totems from afar, and the fury of the earth will be unleashed on all nearby!\n\nNeedless to say... keep a safe distance!", sourceObjective = "Use Tanrir's Overcharged Totem to overload 4 Winterfall Earth Totems.", progress = "Have the totems been destroyed?", completion = "May the Winterfall never threaten the Timbermaw again. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28616] = { id = 28616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormpike Apocalypse", description = "Before we continue, let us have a moment of silence for our fallen brother, Orkus, for without him, we would have been destroyed by the Stormpike onslaught. This is for you, brother!\n\n<Cromush takes a knee.>\n\nNow, {name}, do not think that I forgot your part in all of this! That is why you get the honors of detonating the goblin pocket-nukes.\n\nAre you ready? FOR THE HORDE!", sourceObjective = "Witness the Stormpike Apocalypse.", completion = "With the fingers destroyed and the hand shattered, the Stormpike will have no choice but to scurry back to their cave in Alterac Valley.\n\n<Cromush spits.>\n\nWarchief Hellscream will hear about your bravery, {name}.\n\nAnd rest assured that he will know of the Frostwolf clan's treason!", sourceObjectiveStatus = "unverified-source-field" }
quests[28617] = { id = 28617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flower Power", description = "You know how to use the spitters, but did you know that if you use a sunflower you can grow things faster? We'll grow some sunflowers and then we'll plant some spitters to push back Warden Stillwater's crazed monstrosities.\n\nLet's go!", sourceObjective = "Survive a Massive Wave of Zombies.", completion = "I think that was just the start of it, bud! MORE INCOMING!", sourceObjectiveStatus = "unverified-source-field" }
quests[28618] = { id = 28618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boulder Delivery", description = "Here you go, as promised! One Boulder-in-a-Box.\n\nLilith was asking for this, wasn't she? She's my only customer!", sourceObjective = "Deliver the Boulder-in-a-Box to Lilith the Lithe in Everlook.", progress = "Oh, it's you again. Where's that boulder?", completion = "Ah, you actually brought the boulder! I'm a bit surprised.\n\nStand back and witness the pinnacle of craftsmanship.", sourceObjectiveStatus = "unverified-source-field" }
quests[28619] = { id = 28619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Arathi Highlands!", description = "All able bodied members of the Horde are hereby ordered to report to Dark Ranger Alina at Galen's Fall. The Dark Lady's forces need your help to expand the dominions of the Horde and drive back the Alliance interlopers.\n\nTo reach the Arathi Highlands, travel east from Hillsbrad Foothills and follow the road past Thoradin's Wall.\n\nDestiny calls!", sourceObjective = "Report to Dark Ranger Alina at Galen's Fall in Arathi Highlands.", completion = "At last, the Warchief's reinforcements have arrived. The Dark Lady has plans for you, as she does for us.", sourceObjectiveStatus = "unverified-source-field" }
quests[28620] = { id = 28620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eastpoint Tower", description = "Our outpost in the southeast is having some problems. I don't have any details other than... well, let me just read from the latest letter:\n\n\"The orcs have grown petulant. Send help or I will have them beaten with reeds.\"\n\nThat's it. It was sent from our chief psylosopher, Nils Beerot. Yea, I have no idea what that means either. Could you please head to Eastpoint Tower and find out what he needs? I can't take any more of these cryptic letters!\n\nJust head south and then follow the road east.", sourceObjective = "Speak to Nils Beerot at Eastpoint Tower in Hillsbrad Foothills.", completion = "That imbecile finally sent help, did he? These two orcs are a lost cause. They are stricken with something that I have termed \"Durnholde Syndrome.\" They were both locked up for so long that they grew an affinity for their captors. Now they sit upon my couch with their big, iron balls and cry.\n\nHopefully you will prove to be more useful.", sourceObjectiveStatus = "unverified-source-field" }
quests[28621] = { id = 28621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put That Baby in the Cradle!", description = "Och!\n\nYou an' junior took yer sweet time gettin'  'ere, din't ya!?\n\n<Drinkin' ale/Holdin' hands>, takin' in the sights, I'll wager.\n\nDon't go breakin' yer arm pattin' yerself on the back now, the real work's just beginnin'!\n\nThere be more ta this ancient artifact than ye know, but in order ta reveal its secrets, we need ta get it to the Cradle of the Ancients!\n\nNow howdya spose we do that?\n\nMaybe junior over there has some bright ideas, eh?", sourceObjective = "Speak to Harrison Jones at the Temple of Uldum.", completion = "Of course I have a plan for moving the coffer.\n\nSomeday, maybe the old coot will learn to trust me.", sourceObjectiveStatus = "unverified-source-field" }
quests[28622] = { id = 28622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three if by Air", description = "I had planned on bringing the coffer back to my lab for study, but it seems Brann here has different ideas.\n\nHe thinks he knows how to put a stop to Deathwing's plans here in Uldum.\n\nMy buddy, Jock, is standing by with the transport, just waiting for our signal.\n\nTake these flares and plant them around the perimeter to let him know that we're ready.", sourceObjective = "Use the Signal Flares at the Temple of Uldum.", completion = "Nice work, lad.\n\nLooks as tho everything made the trip in one piece.\n\nI'm beginnin' ta see why junior keeps ye around.", sourceObjectiveStatus = "unverified-source-field" }
quests[28623] = { id = 28623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Push Westward", description = "Our work is done here, {name}.  Against all odds, we stopped the Neferset advance on Nahom.\n\nLet us join the forces pushing west, lest they take all the glory for themselves.\n\nThey must've reached the outskirts of Neferset City by now.", sourceObjective = "Report to King Phaoris at the Neferset City Outskirts in Uldum.", completion = "You've arrived just in time, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28624] = { id = 28624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kilram's Boast", description = "Pah! Crude and clumsy is all I see!\n\nYou need more than just strength. My axes are just as strong as Lilith's maces, but so sharp, I can cut through a tree in one chop!\n\nYou heard me, one chop! I'll prove it, too, here in front of everyone. Go ask Deez if he can get a tree in here!", sourceObjective = "Speak with Deez Rocksnitch.", completion = "They want a tree now? Let's see what I got.", sourceObjectiveStatus = "unverified-source-field" }
quests[28625] = { id = 28625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chop Chop", description = "I deal in small timber plenty, but full trees? That's a novelty item. Kinda like those boulders.\n\nMaybe you can do me another favor. Just west of town there's a grove of trees overlooking Lake Kel'theril. I don't know if it's the spooks there, or all that elf magic junk strewn around the place, but we've been getting treants and lashers wandering around there recently.\n\nThey're making it a real pain to chop wood over there, so why don't you chop some of them? Bring the wood from the treants back here.", sourceObjective = "Collect 10 pieces of Fresh-Cut Frostwood from Frostleaf Treants.", progress = "Show me the lumber.", completion = "Not a bad haul. Maybe we should look into growin' those treants instead...", sourceObjectiveStatus = "unverified-source-field" }
quests[28626] = { id = 28626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tree Delivery", description = "Here you go, one instant Super-Gro Insta-Tree made with 80% natural ingredients!\n\nNo roots, no muss, no fuss. Just give it to Kilram and make sure he stands the heck back when he uses it.", sourceObjective = "Deliver the Super-Gro Insta-Tree to Kilram at the inn in Everlook.", progress = "Chop chop!", completion = "Alright! Stand back now and watch what a true quality weapon can do!", sourceObjectiveStatus = "unverified-source-field" }
quests[28627] = { id = 28627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seril's Boast", description = "Brutes and amateurs.\n\nIt doesn't matter how sharp or heavy your weapon is if all it's good for is hacking like an ogre. I could go on and on about finesse and speed and balance and control... but it's easier to one-up these fools.\n\nTell Deez we've got one more order for him. I need a block of ice.", sourceObjective = "Speak with Deez Rocksnitch.", completion = "Oh, it's you again! I'm so surprised!", sourceObjectiveStatus = "unverified-source-field" }
quests[28628] = { id = 28628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ice Delivery", description = "Alright, one high-quality, pure grade Instant Ice Block!\n\nI tried selling these to people for protection for a while. Y'know, like that trick you see mages pull? Couldn't figure out the whole \"breathing\" thing, though.", sourceObjective = "Deliver the Instant Ice Block to Seril Scourgebane in Everlook.", progress = "Ah, you're back!", completion = "Perfect. Now you'll see what really matters in a weapon... finesse.", sourceObjectiveStatus = "unverified-source-field" }
quests[28629] = { id = 28629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Are We There, Yeti?", description = "My friends are always coming up with great ideas. I've never felt like I could match them... until today! I just drew up the plans for something great! If you promise not to tell, I'll let you in on the secret... \n\nI'm going to make a mechanical yeti! Not only are my friends sure to be freaked out when they see it, but when they get over that, I know they'll be impressed!\n\nI need thick yeti fur from the ice thistle yeti. There's plenty of them in the Ice Thistle Hills to the southeast.", sourceObjective = "Collect 10 Thick Yeti Furs from Ice Thistle Yeti.", progress = "I've got lots to get started on here. Please get me those furs as soon as you can!", completion = "These furs are perfect, {name}. We're off to a great start here!", sourceObjectiveStatus = "unverified-source-field" }
quests[28630] = { id = 28630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo Three", description = "A lot of goblins have been going missing out there in Ice Thistle Hills. I was almost one of them!\n\nI had the idea to set up a sensor to tell us when the yeti were getting close to Everlook. Of course, it's not working either. There's yeti all over the hills and I haven't heard a peep from it.\n\nWould you mind checking on it for me? It might still be fixable. Echo Three's set up to the southeast on the edge of Ice Thistle Hills. Don't ask what happened to Echo One and Two.", sourceObjective = "Find Echo Three.", completion = "Part of this machine is still moving, but on closer inspection it's been severely manhandled. The metal is dented and cracked, and there's huge footprints in the snow all around it.\n\nIn fact, it sounds like something's approaching right now...", sourceObjectiveStatus = "unverified-source-field" }
quests[28631] = { id = 28631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Horns", description = "I can't make a yeti without horns!\n\nI've been looking for what seems like forever for the perfect set of horns... and no horn I find is good enough! But just the other day I saw the biggest yeti in Winterspring.\n\nI named him Icewhomp. His horns are the ones I've been looking for! He lurks all the way in the back of the cave along the eastern ridge of Ice Thistle Hills.\n\nBring me his horns... but be sure to check on Echo Three along the way!", sourceObjective = "Obtain Icewhomp's Pristine Horns.", progress = "Are they perfect? They better be perfect!", completion = "I can't wait to show my friends! Now, just wait a moment while I attach these...\n\nPerfect!", sourceObjectiveStatus = "unverified-source-field" }
quests[28632] = { id = 28632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh From The Hills", description = "Ice this time? Hoo boy, sure. I've got good news and bad news for you.\n\nThe good news is there's a bunch of pure solid ice over in the Ice Thistle Hills cavern, straight east from Everlook. The bad news is there's also a bunch of vicious yetis in there.\n\nBut if you can handle the yeti, hey, piece of cake! Just walk right up to the bigger chunks and crack 'em open with your weapon. Bring it all back to me and I'll do my thing.", sourceObjective = "Collect 7 Pieces of Pure Glacier Ice from the cavern in Icethistle Hills.", progress = "Oh, you're back! How were the yetis?", completion = "Not bad! Let's hope they don't ask for lava or something next, right?", sourceObjectiveStatus = "unverified-source-field" }
quests[28633] = { id = 28633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Coffer of Promise", description = "I'm not quite certain what ta expect 'ere, so stay on yer toes, eh?\n\nThese codes should reveal the coffer's true purpose, and present us with the tools to thwart Deathwing's efforts in Uldum fer good!\n\nStand back!", sourceObjective = "Give Brann Bronzebeard the contents of the Coffer of Promise.", progress = "Well, now.\n\nWould ya look at that!?", completion = "Of course! I had a hunch this is what we'd find.\n\nHad no idea about the organic transformations, though, I must admit.\n\nThere's more to this old relic than I'd dared to hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[28634] = { id = 28634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extinction", description = "Owlbeasts... Soulless, feathered monstrosities sent from the darkest depths of the Twisting Nether to prey upon the weak.\n\n<Nils points to the woods surrounding Eastpoint Tower.>\n\nThey surround us on all sides and they are planning an attack - I can sense it. You must stop them before they can organize.\n\nI want you to head into the forest and kill every owlbeast that you see. NONE SHOULD SURVIVE!", sourceObjective = "Kill 12 Rampaging Owlbeasts.", completion = "The itching has stopped - for now - but they will return.\n\nOh yes, they will return...", sourceObjectiveStatus = "unverified-source-field" }
quests[28635] = { id = 28635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Haunting in Hillsbrad", description = "The battle over Dun Garok was the bloodiest of all the Hillsbrad battles. The dwarves, outnumbered ten-to-one, fought until the bitter end. Every last one of 'em died in defense of that piece of land.\n\nNow I hear claims that the place is haunted. Nobody wants to go near it! Unfortunately I have orders to prepare Dun Garok for habitation.\n\nCould you do me a favor and go to Dun Garok and search for evidence of a haunting? It's far to the southeast.", sourceObjective = "Search Dun Garok for evidence of a haunting.", completion = "Haunted? Ye could say that!", sourceObjectiveStatus = "unverified-source-field" }
quests[28636] = { id = 28636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silence of the Dwarves", description = "The spirits of my soldiers haunt this fort now, <lad/lass>. Their souls are now bound to this place. Even in death they continue to fight for it. 'Tis sad.\n\nPut 'em out o' their misery and perhaps ye shall have the spoils of yer people's victory.", sourceObjective = "Kill 10 Dun Garok Spirits.", completion = "They fight for their land even after death - much like the Forsaken. I will report back to high command that Dun Garok is uninhabitable. Let them keep what they hold so dear.", sourceObjectiveStatus = "unverified-source-field" }
quests[28637] = { id = 28637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste for Bear", description = "Have you ever had the luxury of trying bear meat? I never had the chance to try it in Gilneas, but the bears here are simply exquisite.\n\nThe shardtooth bears that roam just to the south are well-marbled with fat from the cold here. I've been hunting them myself, and it's quite a lark, but I much prefer eating them!\n\nI recommend you try your hand at the hunt. Stick to the white-pelted shardtooth bears, and the Captain will go to field to bring back any you kill.", sourceObjective = "Kill 15 Shardtooth bears.", completion = "Simply splendid! I've been watching the Captain bring bear after bear back to camp and I can't wait to see them thrown on the smoker.\n\nPerhaps I'll have a taste of them raw...", sourceObjectiveStatus = "unverified-source-field" }
quests[28638] = { id = 28638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Owls Have It", description = "I've been eatin' owls my whole life. Owls is good eatin', and my friend Jez agrees. I was the first one that told him to sell owl!\n\nMister fancy-pants worgen here says bears taste better, but don't pay him no mind. You should go hunt yourself some owl. There's plenty of 'em wandering just south of here. Stick to the gray ones for now, an' buzz me on the little talky-thing Jez gave you when you've racked up a few.", sourceObjective = "Slay 15 Winterspring Owls.", sourceObjectiveStatus = "unverified-source-field" }
quests[28639] = { id = 28639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursius", description = "I've heard it said that you are what you eat. I don't know if I believe that, but if it's true... I'd prefer to eat the strongest creature that I can find.\n\nUrsius is the largest bear in Winterspring. He eats first when his pack of shardtooth brings down a chimaera or an owlbear. He claims the most comfortable cave in the shardtooth-held lands. And he has... considerable influence with the shardtooth females.\n\nHe is my kind of bear.\n\nI want to eat him.\n\nHis cave is near the maulers. Good luck!", sourceObjective = "Kill Ursius.", completion = "Ursius is... not delicious.  He tastes like a combination of pinecones and curdled milk, only... oilier.\n\nAre you sure this is Ursius?  The big bear?  In the cave?\n\nThis is horrible.  It honestly tastes like his meat has been steeped in urine.\n\nI don't feel like I'm getting any stronger.\n\nUgh.  It's really bad.  Do you want to try some?", sourceObjectiveStatus = "unverified-source-field" }
quests[28640] = { id = 28640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh Frostsabers", description = "Doesn't that smell great? My smoked meats get top dollar, and nobody else provides the exotic flavors I've got out here in the hills. And it's efficient; you just do the hunting for a small fee, and my other fine friends drag the beasts back here for skinnin' and smokin'!\n\nI've got the market cornered on Frostsaber meat right now. Absolutely delicious stuff, makes great sausages. Head out and hunt those cats just west of here, and we'll call that a start!", sourceObjective = "Slay 15 Frostsabers or Frostsaber Stalkers.", completion = "Alright! Don't stop now, we're after the big ones next!", sourceObjectiveStatus = "unverified-source-field" }
quests[28641] = { id = 28641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride of the Dinner Table", description = "Alright kid, time to head out further into the field!\n\nThis haul's nice and good, but further to the west you'll find much bigger kitties. The pride watchers and huntresses have a lot more muscle on them, and it makes AMAZING burger patties. They sell like crazy!\n\nGimme a ping when you've cleared house and we'll see about you going after the main course.", sourceObjective = "Slay 15 Frostsaber Huntresses or Frostsaber Pride Watchers.", completion = "Beautiful! I'm watching the Captain drag this all back right now and it's a gorgeous sight.\n\nAnd the next course...", sourceObjectiveStatus = "unverified-source-field" }
quests[28643] = { id = 28643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Durnholde Challenge: Zephyrus", description = "Durnholde Keep has always been a place of strife. For years the humans used it as an internment camp and prison for the orcs. After that it was taken over by the Syndicate. Now? The Dark Lady captured and placed powerful elementals within its walls. She charged me with administering \"The Durnholde Challenge.\" Any that can defeat all of the elementals will earn a grand prize! Take this guide and face your first challenge: Zephyrus!\n\nDurnholde is located just northeast of us.", sourceObjective = "Kill Zephyrus.", completion = "Zephyrus was a mighty adversary. Surely the remaining elementals will challenge you further!\n\n<You open the guide that Jekyll gave to you.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28644] = { id = 28644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Durnholde Challenge: Teracula", description = "According to the guide, Teracula is your next challenge. It roams the path just outside of Zephyrus' lair.", sourceObjective = "Kill Teracula.", sourceObjectiveStatus = "unverified-source-field" }
quests[28645] = { id = 28645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Durnholde Challenge: Bloodvenom", description = "According to the guide, Bloodvenom is your next challenge. The fearsome elemental can be found on the lower level of Durnholde Keep, near the western prisons.", sourceObjective = "Kill Bloodvenom.", sourceObjectiveStatus = "unverified-source-field" }
quests[28646] = { id = 28646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Durnholde Challenge: Infernus", description = "According to the guide, Infernus is your next challenge. This being, made of molten lava and raging fire, can be found on the lower level of Durnholde Keep, near the eastern prisons.", sourceObjective = "Kill Infernus.", sourceObjectiveStatus = "unverified-source-field" }
quests[28647] = { id = 28647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Durnholde Challenge: D-1000", description = "Imprisoned in the old Durnholde Keep arena is a being comprised of pure mercury. The Forsaken have dubbed it the D-1000. Kill the D-1000 and claim your prize!", sourceObjective = "Kill the D-1000.", completion = "This is the first time anyone has actually completed the challenge. You truly are a powerful {class}, {name}. As promised, choose your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[28649] = { id = 28649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty worgen in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Lord Harford, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[28650] = { id = 28650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty goblin in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Gally Lumpstain, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[28651] = { id = 28651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Novice Elreth", description = "Now that the training's done and out of the way, why don't you go speak with Elreth?  She serves Shadow Priest Sarvis, and will probably have some tasks to which you can apply your new abilities.", sourceObjective = "Speak to Novice Elreth at Deathknell in Tirisfal Glades.", completion = "May the Dark Lady watch over you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28652] = { id = 28652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caretaker Caice", description = "I am done with you.  There are, however, others who can use your aid.\n\nCaretaker Caice, standing on that stump behind me, can probably give you another assignment.  You should speak with him now.", sourceObjective = "Speak with Caretaker Caice at the Deathknell Graves in Tirisfal Glades.", completion = "Yes?  And who might you be?", sourceObjectiveStatus = "unverified-source-field" }
quests[28653] = { id = 28653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Priest Sarvis", description = "Are you still here, {name}?  You know, I'm only a deathguard.  I don't have many tasks I can hand out to passers-by like you.\n\nI'd recommend that you talk to Shadow Priest Sarvis.  I remember, he helped me get on my feet after I was plucked out of that tomb.  I'm sure he'll do the same for you.\n\nYou'll find him just inside the chapel, here on the west side of town.", sourceObjective = "Speak with Shadow Priest Sarvis at Deathknell in Tirisfal Glades.", completion = "Greetings, {name}.\n\nI see you wield a weapon.  Can you fight?", sourceObjectiveStatus = "unverified-source-field" }
quests[28654] = { id = 28654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Matter", description = "Well, <laddie/little lady>, half of me wishes I could stick around a while and take in the sights with ye.\n\nI've seen some mighty amazin' things in my day, but this here takes the cake.\n\nSadly, I have a fair bit o' research ta do on these discs before I make my way into the Halls of Origination.\n\nYou seem ta be worth your salt, perhaps ye'd like ta tag along and see how a REAL archaeologist works, eh?", sourceObjective = "Brann Bronzebeard wants you to meet him in the Halls of Origination.", completion = "Bout time ye showed up, lad.\n\nNow let's get goin'! There be work ta do!", sourceObjectiveStatus = "unverified-source-field" }
quests[28655] = { id = 28655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild, Wild, Wildhammer Wedding", description = "We are ready to begin, {name}!\n\nBut I have it on good authority that the Twilight's Hammer may try to disrupt the ceremony, so as to demoralize and destroy the Wildhammer. Things could get dangerous!\n\nFor this reason, I will be performing the ceremony myself, so that I can keep the bride and groom close to me. Sound like a plan? Good!\n\nSince her father is dead and her brother the best man, Fanny has asked that you walk her down the aisle. What an honor! Talk to me when you're ready to begin.", sourceObjective = "Talk to Grundy MacGraff to begin the wedding ceremony. Kill any Twilight's Hammer that try to stop it!", progress = "It's a nice day for a Wild wedding...", completion = "We did it, {name}! Fighting that ... thing side-by-side really brought all the Wildhammers together. The heads of the families are more united than I've ever seen them. Drink up, {name}, and celebrate!!\n\nOf course, our work is only beginning. I'll rally our new Wildhammer reinforcements with the rest of the Alliance and prepare to storm the Twilight Bastion.\n\nI'm sure we'll meet again soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[28656] = { id = 28656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Life Forces", description = "When this creature died, some sort of energy was released from its body. The energy was passed on to you, and now you feel somewhat stronger.\n\nAccording to Winterspring locals, Witch Doctor Mau'ari at the Snowden Chalet is an expert in the wildlife of the area. She might know something about this mysterious energy.", sourceObjective = "Speak with Witch Doctor Mau'ari at the Snowden Chalet in Winterspring.", completion = "What's dis? You got de smell of de E'ko on ya! Let Mau'ari tell ya a little bit about de E'ko and what it do.\n\nYou're lucky, {race}. De E'ko searched you out. A troll like me's gotta go find de E'ko herself.\n\nAll de creatures of Winterspring have E'ko. De furbolg, de chillwind, de shardtooth... even de Ice Thistle yeti! You kill dese creatures, and sometimes, a bit of E'ko comes out. Different creatures... different E'ko.\n\nGo on now. Go find de other E'ko!", sourceObjectiveStatus = "unverified-source-field" }
quests[28657] = { id = 28657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Huge Problem", description = "We finally capture this godforsaken rock and then we find out that there is a huge ettin roaming around, taking out our sentry patrols!\n\n{name}, I need you to round up a few friends and take that ettin down.  We can't have a beast like that roaming around, wreaking havoc.\n\nStay alert, reports from the front say that he is carrying a huge tree as a weapon, and he is not afraid to use it.", sourceObjective = "You have been asked to kill Problim, a giant ettin that roams the paths of Tol Barad.", progress = "Did you find problim yet?  Pretty hard to miss that guy with how huge he is.", completion = "You actually killed him?!  I can't believe it!", sourceObjectiveStatus = "unverified-source-field" }
quests[28658] = { id = 28658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swamp Bait", description = "Supplies are never easy to find in a place like this, {class}.  We have been scouting since we captured the island but things are not looking good.\n\nFortunately, we just  received a scouting report that a swamp full of crocs is just west of our base camp here.  The hides off those crocs will come in handy for our leatherworkers.  Bring back as many as you can.", sourceObjective = "You have been tasked with collecting 8 Crocolisk Hides from the Baradin Crocolisks on Tol Barad. The crocolisks can be found in the swamp, just west of Baradin Hold.", progress = "You cleared out that swamp yet?", completion = "Looks like you were able to get the croc hides that we needed.  Thanks {name}, your contributions will not go unnoticed.", sourceObjectiveStatus = "unverified-source-field" }
quests[28659] = { id = 28659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Leftovers", description = "We fought hard to capture this island, {race}.  We cleared out most of the Alliance filth but I can still smell their foul stench in the air.\n\nI need you to investigate the slagworks, warden's vigil and the ironclad garrison.  Kill any Alliance that you find.\n\nYou know what they say, the only good Alliance is a dead Alliance!", sourceObjective = "You have been instructed to kill 12 Alliance Infantry on Tol Barad. You can find the holdouts in The Slagworks, Warden's Vigil and the Ironclad Garrison, here on Tol Barad.", progress = "Gah, the smell of their weak bodies is sickening me.", completion = "Those filthy alliance never stood a chance.  Nice work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28660] = { id = 28660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Depths", description = "You are a sight for sore eyes, {name}.  Now that we have claimed tol barad, the battle has just begun.\n\nWe discovered a cell block just east of here that we need you to clear out.  Turns out that its chock full of ghosts that have been locked up down there for who knows how long.\n\nClear out as much as you can and report back to me when you are done.", sourceObjective = "You have been asked to kill 9 ghosts of any type in the Cursed Depths, just east of Baradin Hold.", progress = "Did you take care of the ghosts down there yet?  We have plenty of horde scum to fill that place up with once it's cleared out.", completion = "You made it back out alive?  You are a stronger man than I, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28661] = { id = 28661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Imprisoned Archmage", description = "We have been trying to clear out the Cursed Depths cellblock since we landed on Tol Barad.  It seems that everytime we get close, that archmage shows up and pushes us back.\n\nNow that we have claimed the island, it's time we take another shot.  Head down there and bring me back his staff as proof that you have finished the job.", sourceObjective = "You must kill Archmage Galus and return with his Staff from the Cursed Depths, just east of Baradin Hold.", progress = "Have you been able to take out the Archmage?", completion = "Galus is dead?  Fantastic work {name}, now we can send down the cleanup crew and get that cellblock ready for new prisoners.", sourceObjectiveStatus = "unverified-source-field" }
quests[28662] = { id = 28662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning From The Past", description = "Now that we finally have a hold on this wretched island, we can start to investigate how it got in this condition.  Some of our troops have discovered journals around the entrance to Cursed Depths cellblock just east of here.\n\nThese journals are of particular interest to our elder scribes back at base camp.  I need you to recover four of them and bring them back to me as fast as you can.\n\n{name}, be careful down there, that place is crawling with undead.", sourceObjective = "You have been asked to recover four Dusty Prison Journals from the Cursed Depths, just east of Baradin Hold.", progress = "Were you able to recover the journals?  Reports mentioned that they were sighted both in and out of the cells down there.", completion = "These journals are in excellent condition {name}.  We will begin deciphering them immediately.  Only time will tell what secrets they hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[28663] = { id = 28663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "D-Block", description = "Have you heard of the D-Block yet {name}?  It's one of the old cellblocks here on the island.  Problem is, it's infested with demons.  We planned on using it to lock up the leftover Alliance we found on the island, but that is not going to happen in its current state.\n\nI need you to head down there and clear those demons out.  Report back to me when you are done.", sourceObjective = "You have been instructed to kill 10 demons of any type in the D-Block, just northwest of Baradin Hold.", completion = "D-Block is all clear?  Good work, {name}.  We will send down a crew to start cleaning up right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[28664] = { id = 28664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Svarnos", description = "Excellent work on the island capture, {class}.  Now that we have claimed the island, we need to make these cellblocks useable for prisoners.  D-Block has been especially hard to clear out.  Unfortunately it has become overrun with demons of all sorts.\n\nWe have been able to thin out the demons but a large core hound has broken its way out of its cell and is wreaking havoc down there.  I need you to kill him and bring back his collar.", sourceObjective = "You must kill Svarnos in the D-Block and return with his Cursed Collar. Svarnos can be found in the D-Block, just northwest of Baradin Hold.", progress = "Is the core hound dead?", completion = "Svarnos is finally dead?  Looks like we can finally get to work setting up that cellblock then.  Thank you {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28665] = { id = 28665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed Shackles", description = "Have you been down in the D-Block yet, {name}?  Every time we clear that infested cellblock out, the demons seem to return rather quickly.  We learned that they regenerate from the cursed shackles scattered around the area.  That's where you come in to the picture {name}.\n\nI need you to retrieve as many of those shackles as you can and bring them back to me.  We will destroy them immediately.", sourceObjective = "You have been asked to recover 8 Cursed Shackles from the D-Block, just northwest of Baradin Hold.", progress = "Did you find many shackles?  Reports mentioned that they were all over the place down there.", completion = "The shackles!  We will begin the process of destroying these shackles immediately {name}.  Thank you for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28666] = { id = 28666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Burning Steppes!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to John J. Keeshan at Flamestar Post.\n\nYour aid is urgently needed to put an end to the Blackrock orc menace!\n\nYou can reach the Burning Steppes by traveling south from the Searing Gorge through Blackrock Mountain. Look for Flamestar Post on the far side of the mountain.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to John J. Keeshan at Flamestar Post in the Burning Steppes.", completion = "It's time for the Blackrock orcs to feel the full wrath of the Alliance. They will pay for what they've done.", sourceObjectiveStatus = "unverified-source-field" }
quests[28667] = { id = 28667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Burning Steppes!", description = "All able bodied members of the Horde are hereby ordered to report to Ariok at Flamestar Post.\n\nHonored Eitrigg's son, Ariok, needs your assistance to halt the blind aggression of the Blackrock orcs before they invade the neighboring lands.\n\nYou can reach the Burning Steppes by traveling south from the Searing Gorge through Blackrock Mountain. Flamestar Post will be south of the mountain.\n\nDestiny calls!", sourceObjective = "Report to Ariok at Flamestar Post in the Burning Steppes.", completion = "We must stop the Blackrock orcs before they can expand their influence.", sourceObjectiveStatus = "unverified-source-field" }
quests[28668] = { id = 28668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prison Revolt", description = "We have the island, now we need to put the resources here to work.  We found an abandoned cellblock just southwest of here and we need you to go check it out {name}.\n\nReports have come back that it is overrun with prisoners that have been stuck down there for years.  Do whatever you need to do to clear that place out.  Report back to me when you are done.", sourceObjective = "You have been instructed to kill 10 prisoners of any type in The Hole, just southwest of Baradin Hold.", progress = "Were you able to clear out that cellblock {name}?  We are waiting on you.", completion = "You cleared that area out?  Looks like you might be more useful to us that we thought, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28669] = { id = 28669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden", description = "We have almost finished clearing out the revolting prisoners in the hole, but one last problem remains.  The warden.\n\nWarden Silva is their master and they will do anything for him.  If we take him out, we take them all out.  Finish him off and bring me back his keys.  We can use those keys to explore deeper into the cellblock and possibly gain access to the water supply here on the island.", sourceObjective = "You must kill Warden Silva in The Hole and return with his keys. The Hole is just southwest of Baradin Hold.", progress = "Is the warden dead yet?", completion = "Ahh, the wardens key's.  Another job well done, {name}.  These will come in very handy.", sourceObjectiveStatus = "unverified-source-field" }
quests[28670] = { id = 28670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Food From Below", description = "Supplies are running low here in camp, {name}.  We have recently learned that the cellblock just southwest of here has a number of rations remaining from years of use.  We need you to gather as many of those as you can and bring them back to camp.\n\nOne more thing, the entire cellblock is overrun with prisoners so be careful.", sourceObjective = "You have been asked to recover 12 Cellblock Rations from The Hole, just southwest of Baradin Hold.", progress = "Were you able to recover the rations?  Reports mentioned that they could be found all over the place down there.", completion = "These rations will really help the troops out {name}.  Thank you for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28671] = { id = 28671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Blasted Lands!", description = "All able bodied members of the Horde are hereby ordered to report to Okrilla at Dreadmaul Hold.\n\nOkrilla, commander of the Horde forces at Dreadmaul Hold, requires your help to secure the outpost against rebellious ogres and the forces of the Alliance.\n\nTravel to Dreadmaul Hold by taking the road south from the Swamp of Sorrows.\n\nDestiny calls!", sourceObjective = "Report to Okrilla at Dreadmaul Hold in the Blasted Lands.", completion = "Our enemies are numerous, {class}. It will take skill and bravery to overcome them all.", sourceObjectiveStatus = "unverified-source-field" }
quests[28672] = { id = 28672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Executor In the Field", description = "I can keep you busy here in town all week... but you seem to be more the fighting type.\n\n<Elreth looks you over and nods.>\n\nYes, you'll do just fine.  I'd like you to go talk to Executor Arren.  Follow the path north, out of Deathknell.  You'll find him not far past the barricades.", sourceObjective = "Report to Executor Arren.", completion = "What do we have here?  A new {class}, ready for battle, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[28673] = { id = 28673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Blasted Lands!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Quartermaster Lungertz at Nethergarde Keep.\n\nNethergarde's garrison urgently needs your help to stem the Horde advance into the Blasted Lands! Travel south from the Swamp of Sorrows and follow the road east to reach Nethergarde Keep.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Quartermaster Lungertz at Nethergarde Keep.", completion = "For decades has the garrison at Nethergarde held firm against the threat of the Horde and we do not intend to surrender now.", sourceObjectiveStatus = "unverified-source-field" }
quests[28674] = { id = 28674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starfall Village", description = "You've been pretty busy around here. If you're still eager to do good deeds, or just get paid, I've got something you might be interested in.\n\nStarfall Village is just northwest of Everlook. The night elves there recently suffered a pretty nasty bug infestation, and they're asking for any help they can get.\n\nA few goblins from here already went there to start exterminating, but I'm sure there's room for more. Talk to Wynd Nightchaser, he'll fill you in.", sourceObjective = "Speak with Wynd Nightchaser at Starfall Village.", completion = "Welcome to Starfall, {class}. We have opened our doors to all travelers in our time of need.", sourceObjectiveStatus = "unverified-source-field" }
quests[28675] = { id = 28675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Swamp of Sorrows!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Trade Baron Silversnap at Bogpaddle.\n\nThe Alliance forces urgently needs the munitions provided by the baron! You must do whatever is necessary to convince the baron to keep selling our forces supplies at reasonable prices.\n\nTo get to the swamp, follow the road from the southeastern Burning Steppes through the Redridge Mountains.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Trade Baron Silversnap at Bogpaddle in the Swamp of Sorrows.", completion = "Welcome to Bogpaddle, {class}. I fully expect you will enjoy all our facility has to offer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28676] = { id = 28676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exterminators at Work", description = "The infestation of our barrow den occured nearly overnight. Vicious creatures never before seen in these lands swarmed the tunnels, hatching from unseen eggs.\n\nWith the few of us here, it was all we could do to keep them from spreading outside the den. We were forced to hire goblins from Everlook that claimed expertise in extermination, but they have not yet been successful.\n\nIf you wish to assist them, enter the barrow den to the west of this lodge and speak with Rinno Curtainfire.", sourceObjective = "Speak with Rinno Curtainfire inside the Ban'Thallow Barrow Den.", completion = "Oh good, another warm body!\n\nI hope that elf up there didn't bore you to death. We've got a lot of bugs to kill here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28677] = { id = 28677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Swamp of Sorrows!", description = "All able bodied members of the Horde are hereby ordered to report to Trade Baron Silversnap at Bogpaddle.\n\nPersuade the trade baron to continue supplying our warriors with the weapons and munitions they require, no matter what it takes!\n\nTravel to the Swamp of Sorrows by following the road from the southeastern Burning Steppes through the Redridge Mountains and meet the trade baron at his seaside resort.\n\nDestiny calls!", sourceObjective = "Report to Trade Baron Silversnap at Bogpaddle in Swamp of Sorrows.", completion = "Welcome to beautiful Bogpaddle!", sourceObjectiveStatus = "unverified-source-field" }
quests[28678] = { id = 28678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain P. Harris", description = "The Cape of Lost Hope has been a sore in our side for weeks here on Tol Barad.  Half of our supply ships end up on the rocks down there.\n\nTo make matters worse, it's been overrun by a gang of undead sailors.  We have tried thinning the ranks, but they just seem to keep coming back.  Our last resort is to try and take out the captain that they report to.  You should be able to find him on a ship, just off the shoreline.\n\nOh, and I hope you are not too scared of sharks.", sourceObjective = "You have been tasked with killing Captain P. Harris at the Cape of Lost Hope. The Cape of Lost Hope can be found northwest of here, along the coast. Just look for the shipwrecks.", completion = "You did it!  Maybe we can finally get some ships into port now.  Thank you {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28679] = { id = 28679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattling Their Cages", description = "We have been having issues with the undead down at the Cape of Lost Hope for a while now.  Every time a new ship wrecks, they end up getting more undead to join their ranks.\n\nCan you do us a favor and thin out the ranks up there?  I know you won't be able to kill them all, but anything you can do will help at this point.\n\nKeep an eye out for alliance, we have been getting reports of them ambushing the beach lately.", sourceObjective = "3rd Officer Kronkar has asked you to kill 8 Shipwrecked Sailors at the Cape of Lost Hope. The cape is located due northwest of here, on the beach.", completion = "Nice work on the undead up there {name}.  We really appreciate the help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28680] = { id = 28680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boosting Morale", description = "Morale is low these days, {name}.  We make every effort we can to keep the troops in high spirits but we are running low on our main supply of morale booster... rum.\n\nI have been getting reports from our infantry to the south that the shipwrecks on the Cape of Lost Hope still have a good supply of southsea rum in their wrecked hulls.  Can you head up there and investigate?\n\nBring back any rum you can find.", sourceObjective = "You have been asked to recover 6 Barrels of Southsea Rum from the shipwrecks on the Cape of Lost Hope. The cape can be found north of here, along the coast.", progress = "Were you able to recover the rum?  I would try but I am deathly afraid of the water.  Not to mention that crazy shark.", completion = "This rum will really help us out, {name}.  They might not feel great in the morning but at least they will go to sleep happy.", sourceObjectiveStatus = "unverified-source-field" }
quests[28681] = { id = 28681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shark Tank", description = "I hate sharks.  All of my troops hate sharks too.  This is where you come in, {name}.\n\nI need you to head up to the Cape of Lost Hope and take out a huge shark named Tank.  Tank is not to be trifled with so I would bring a few friends if I were you.", sourceObjective = "You have been tasked to kill Tank, a large shark cruising the waters of the Cape of Lost Hope. The cape can be found north of here, along the northern coastline.", progress = "I don't think you guys have a chance against that shark.", completion = "No way, you actually killed him?  We are having shark tacos tonight for sure!", sourceObjectiveStatus = "unverified-source-field" }
quests[28682] = { id = 28682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming The Keep", description = "Have you seen the keep on the north side of the island, {name}?  That is where Keep Lord Farson runs his operation from.\n\nFarson has a small group of dedicated followers and they have been giving us trouble since we got here.  We sent a small group to investigate and they reported back on his exact position within the keep.\n\nCan you finish him off for us?", sourceObjective = "You have been asked to kill Keep Lord Farson at the Farson Hold. Farson Hold can be found on the north side of the island.", progress = "Is keep lord farson dead?", completion = "You killed him?  We have been trying to take that guy out for weeks!  We thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28683] = { id = 28683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the Brood", description = "We have been trying to get a foothold in The Darkwood for weeks now but that forest is infested with spiders.  Do me a favor and see if you can thin them out enough for us to set up an attack.\n\nCareful out there, I have heard reports of Alliance troops nearby earlier in the week.", sourceObjective = "Kill 12 Darkwood Lurkers in The Darkwood. The Darkwood forest is just north of here, across the bridge on the central island.", completion = "Nice work on those spiders, {name}.  At this rate, we will be taking that forest in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[28684] = { id = 28684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sticky Task", description = "Finding supplies on the island has been difficult, to say the least.\n\nFortunately, we have found a good supply of silk in The Darkwood, just north of here.  The bad part of this story is that the silk comes from the glands on Broodmother spiders.  I need you to gather 4 of these for me.\n\nThat should be just enough to finish up this last set of shirts.", sourceObjective = "Collect 4 Sticky Silk Glands from Darkwood Broodmother spiders in The Darkwood. The Darkwood forest is just west of here, across the bridge on the central island.", progress = "Were you able to gather the sticky silk glands?", completion = "These glands will do nicely.  We are grateful for your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28685] = { id = 28685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Weapon Behind", description = "Battle supplies are hard to come by on this rock.  Every time we hold off another Alliance attack, it feels like we are fighting with sticks and stones.\n\nReports have come in that Keep Lord Farson on the north side of the island has a large stockpile of rifles that we could use.  Can you head down there and check it out?\n\nBe careful {name}, Farson's followers will do anything to protect him.", sourceObjective = "Retrieve 12 Rusty Rifles from Farson Hold on the north side of Tol Barad Peninsula.", progress = "Any luck with those rifles?", completion = "Thanks for rounding these up for us, {name}.  Kind of hard to fight a battle without any guns.", sourceObjectiveStatus = "unverified-source-field" }
quests[28686] = { id = 28686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not The Friendliest Town", description = "Have you been up to Rustberg Village yet {name}?  I would suggest you bring a sharpened blade if you are heading that direction.\n\nThe folks in that town look alright but something suspicious is going on in there.  Reports have been coming in that they are picking off our soldiers left and right.  We have had just about enough of that, so I need you to head down there and do a little cleaning house for us.\n\nTake down as many as you can and report back when you are done.", sourceObjective = "Commander Larmash has asked you to kill 14 villagers in Rustberg Village. Rustberg Village is just north of base camp, on the right side.", progress = "Did you find out what's up with that village?  Something seems off...", completion = "Told you that village was full of wackos.  Nice job clearing it out {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28687] = { id = 28687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teach A Man To Fish.... Or Steal", description = "Rustberg Village.  That place is a curse and a blessing for us, {name}.  I have no clue where bandits learned to fish as well as they do but I have no time to worry about that now.\n\nI need you to head down there and steal as many of their fish reserves as possible.  We have been living off scraps since we retook the island and this is our best chance at some solid food reserves.\n\nKeep an eye out for stealthers up there, reports have told us they are prevalent inside the village walls.", sourceObjective = "You must steal 22 Rustberg Seabass from Rustberg Village. The fish can be found on string stands at the docks, round back of the village. Rustberg Village is due north of base camp, on the right side.", progress = "Were you able to pull off the heist and get us some fish?", completion = "These fish will do nicely, {name}.  Keeping the troops fed and in good condition is our number one priority and you really came through for us here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28688] = { id = 28688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Northern Stranglethorn Vale!", description = "All able bodied members of the Horde are hereby ordered to report to Commander Aggro'gosh at Grom'gol Base Camp. The commander requires your aid to keep the supply routes open and free of interference from the local inhabitants and the troublesome Alliance.\n\nTo reach Grom'gol, you can take the zeppelin Orgrimmar's eastern zeppelin tower or the one near Undercity.\n\nDestiny calls!", sourceObjective = "Report to Commander Aggro'gosh at Grom'gol Base Camp in the Northern Stranglethorn Vale.", completion = "At last, the Warchief's reinforcements have arrived.", sourceObjectiveStatus = "unverified-source-field" }
quests[28689] = { id = 28689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forgotten", description = "Many soldiers died on this island {name}.  It is only fair that we pay our respects to them in any way that we can.\n\nI need you to travel to Forgotten Hill, due west of here and release our brothers in arms' tortured souls away from this place.  Do be careful over there, reports of undead have been ongoing in the area.", sourceObjective = "Release the spirits of 6 tortured souls at Forgotten Hill. Souls can be channeled by touching your hands directly to the gravestones. Forgotten Hill is due west of here, past The Restless Front.", completion = "May their souls rest in peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[28690] = { id = 28690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging the Remains", description = "Forgotten Hill has been overrun with zombies and ghouls ever since we reclaimed this wretched isle.  We have tried to clear them out many times but they always seem to come back.\n\nOne of our lieutenants recommended taking the ghouls' bones when we kill them in hopes that they can't reincarnate overnight.  Think you can help us out with this one?", sourceObjective = "You need to recover 9 Cursed Femur bones from the ghouls that inhabit Forgotten Hill. Forgotten Hill is on the west side of the island, just past The Forgotten Front.", progress = "Were you able to recover the femur bones?  Better for you to try than me.", completion = "I didn't think you would be able to do it, {name}.  You are just full of surprises aren't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[28691] = { id = 28691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Lieutenant Connor", description = "The first time I heard about Lt. Connor, I was just a young recruit in Ragefire Chasm.  None of us could believe he ended up here on Tol Barad.  Sadly, he still roams these wretched islands, wreaking havoc on our troops morale.\n\nI need you to put an end to his misery... and ours.", sourceObjective = "Find and kill First Lieutenant Connor at Forgotten Hill. You will find Forgotten Hill on the far west side of the island.", progress = "Is First Lieutenant Connor a goner?", completion = "Hey, you made it back alive!  Can't say you were the first one to try this task, but you are definitely the first one to make it back alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[28692] = { id = 28692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magnets, How Do They Work?", description = "Getting useful machine parts out here on the island has been difficult, {name}.  We have been trying to repair the broken siege engines here in camp but we keep running out of useful parts.\n\nOur second regiment reported some wrecked out siege engines in a old battlefield to the west.  Maybe we could find some parts over there?\n\nYou are going to have trouble finding anything in that old battlefield so take this magnetized scrap collector and put it to some good use.", sourceObjective = "You have been tasked with recovering 7 pieces of Siege Engine Scrap. Use the Magnetized Scrap Collector in The Restless Front to find the scraps. The Restless Front is due west, just past the second bridge.", progress = "Did that magnet contraption actually work?", completion = "These parts will really help us out, {name}!  Who would have thought you can find stuff this useful in all that old junk?", sourceObjectiveStatus = "unverified-source-field" }
quests[28693] = { id = 28693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish The Job", description = "We have been trying to collect useful scraps from the front all week.  Every time we gather a batch to bring back to camp, we get assaulted by the restless soldiers in the area.  Can you head over there and clear them out?", sourceObjective = "Kill 5 Restless Soldiers at the Restless Front. You can find the front on the west side of the island, just before Forgotten Hill.", progress = "Were you able to finish the job?", completion = "It's about time someone took those guys out.", sourceObjectiveStatus = "unverified-source-field" }
quests[28694] = { id = 28694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watch Out For Splinters!", description = "Have you been over to the Wellson Shipyard yet, {name}?  Best to stay away from there unless you have a good reason to venture in.  Unfortunately, that is exactly what I need you to do.\n\nYou see, we have been short on supplies ever since we recaptured the island.  That ghost ridden shipyard is overflowing with lumber but every time we send an escort to recover the lumber, they never make it back.\n\nCan you help us out?", sourceObjective = "Private Sarlosk has asked you to recover 15 pieces of Shipyard Lumber from the Wellson Shipyard. The lumber can be recovered from the ghosts in the shipyard or found lying around the premises. The shipyard can be found northwest of here, on the coast.", progress = "Did the ghosts scare you off?", completion = "I didn't think you would be able to do it, {name}.  You are just full of surprises aren't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[28695] = { id = 28695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Foreman Wellson", description = "Foreman Wellson has been a pain in our side since we got here.  His shipyard holds a large amount of supplies that would be extremely useful to us... if we could get to them.\n\nHe keeps a close watch over his minions and makes it very difficult for us to get a foothold on the shipyard.  I need you to take out Wellson for good this time.  Be careful {name}, we have been receiving reports of dirty Alliance all around the area.", sourceObjective = "Kill Foreman Wellson at the Wellson Shipyard. The shipyard can be found north of here, on the western coast.", completion = "Great work {name}.  I will report your efforts to our highest in command immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[28696] = { id = 28696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombs Away!", description = "The Wellson Shipyard is constantly receiving supplies from offshore and we need to put a stop to it.  They have setup cannons along the docks for defense but if you can make it to them, we can use them to destroy their supply ships.\n\nHead down there and see what you can do.  Report back to me on your progress.", sourceObjective = "Destroy 10 Ghastly Supply Boats.", progress = "Did you take out the boats?", completion = "Great work on those supply ships, {name}!  We knew you would be good for somethin' around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28697] = { id = 28697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghostbuster", description = "See that hill with the towers to the northeast?  That's Largo's Overlook and it's not a fun place to set up camp next to.  We have been dealing with those spirits and spectres ever since we setup camp.\n\nCan you head up there and let them know we don't plan on leaving anytime soon?  A few good kills on their ranks should put them in line.\n\nThanks for your help on this, {name}.", sourceObjective = "Kill 14 ghosts of any type at Largo's Overlook, northeast of the Horde camp.", progress = "Who's afraid of ghosts?  Not me.  Well, maybe in the dark.", completion = "Great work, {name}!  We should not hear from the ghosts again anytime soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[28698] = { id = 28698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannonball!", description = "Largo and his minions have been stealing our supplies ever since we setup camp here.  It's frustrating to say the least.\n\nWe have heard reports that he is stockpiling cannonballs in the towers overlooking the water up on his overlook.  Can you head up there and try to recover some of them for us?\n\n{name}, don't forget to keep a watch out for Alliance too.", sourceObjective = "You need to recover 4 Stacks of Cannonballs from Largo's Overlook for Private Sarlosk. You can find Largo's Overlook just northeast of the base camp.", progress = "Did you find the cannonballs?", completion = "Good job on the recovery effort {name}. These cannonballs should last us a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[28699] = { id = 28699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Northern Stranglethorn Vale!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Lieutenant Doren at the Rebel Camp.\n\nYears after Colonel Kurzen's treachery against Stormwind, the truth of what happened remains a mystery. Aid the survivors in learning what became of the colonel. Travel south from Duskwood and follow the road west after crossing into the jungle to reach the Rebel Camp.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Lieutenant Doren at the Rebel Camp in the Northern Stranglethorn Vale.", completion = "Welcome to our camp, {class}, such as it is.", sourceObjectiveStatus = "unverified-source-field" }
quests[28700] = { id = 28700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Overlook Back", description = "There is only one way for us to take Largo's Overlook back.\n\nI think you know what we need to do {name}.  Largo is pretty paranoid these days so you should be able to find him on top of the tower, looking for his imaginary navy to finally arrive.", sourceObjective = "Private Sarlosk has asked you to kill Commander Largo at Largo's Overlook. The overlook is just northeast of the base camp.", progress = "Were you able to take out Largo?", completion = "Ha, we finally got Largo!  Nice one, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28701] = { id = 28701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Harm's Way", description = "Luckily, when the infestation occured, no druids were slumbering in the western barrow den. It is still a sacred site to us, however, and its depths hold blessed relics kept there undisturbed for ages.\n\nWhile I am somewhat trusting of the goblin exterminators, I am also... familiar with the habits of their race. Please retrieve any relics you can find in the barrow den and bring them back to me so they are not damaged. They are within urns, nestled in the small alcoves throughout the den.", sourceObjective = "Retrieve 5 Starfall Relics from the Ban'Thallow Barrow Den.", progress = "I hope you found them intact...", completion = "They may not look like much to you, but these relics hold great value to the people of Starfall.  You are kind, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28702] = { id = 28702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: The Cape of Stranglethorn!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Bronwyn Hewstrike at the Explorers' League Digsite.\n\nThe Explorers' League expedition needs your help to safeguard its site and findings from marauding ogres. Travel south from Northern Stranglethorn Vale and follow the road to the Explorers' League Digsite.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Bronwyn Hewstrike at the Explorers' League Digsite on the Cape of Stranglethorn.", completion = "It's good to see you here, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28703] = { id = 28703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Into My Barrow", description = "I've still got no clue where all these bugs came from. My best guess is the cataclysm stirred up some underground nests we never knew about.\n\nNo use getting distracted with that when they need killing, though!", sourceObjective = "Kill 10 Coldlurk Creepers and 5 Coldlurk Burrowers.", completion = "Hey, nice work!\n\nIf you ever want to come back and kill some more bugs for absolutely no additional reward, please, feel free!", sourceObjectiveStatus = "unverified-source-field" }
quests[28704] = { id = 28704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: The Cape of Stranglethorn!", description = "All able bodied members of the Horde are hereby ordered to report to Sassy Hardwrench at Hardwrench Hideaway. She requires your help to deal with the pirates and naga who have overrun the jungle.\n\nTravel to Hardwrench Hideaway by heading south from Northern Stranglethorn and looking for the town southwest of the Gurubashi Arena.\n\nDestiny calls!", sourceObjective = "Report to Sassy Hardwrench at Hardwrench Hideaway on the Cape of Stranglethorn.", completion = "Welcome to Hardwrench Hideaway!", sourceObjectiveStatus = "unverified-source-field" }
quests[28705] = { id = 28705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Outland!", description = "All able bodied members of the Horde are hereby ordered to report to Lieutenant General Orion at the Stair of Destiny.\n\nYour skills are needed to fight the Burning Legion's presence on the shattered remnants of Outland.\n\nGo to Orgrimmar's Cleft of Shadow and use the portal near the mage trainers to reach the Blasted Lands, then travel through the Dark Portal itself to reach Hellfire Peninsula.\n\nDestiny calls!", sourceObjective = "Report to Lieutenant General Orion at the Stair of Destiny in Hellfire Peninsula.", completion = "Prepare yourself for battle. The Horde has need of you here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28706] = { id = 28706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spray it Forward", description = "My fellow siblings are already further down in the den trying to deal with these bugs, and they're starting to get overwhelmed. I say it's time to gas the place.\n\nTake these fumigators. Don't go setting them off yourself; it takes a highly trained professional, and proper timing. Just find my sisters and pass them out.\n\nRemma should be positioned closest to the entrance. Head down the corridor and  keep to your right once you go down the ramp.", sourceObjective = "Bring the Box of Bugkill Fumigators to Remma Curtainfire inside the Ban'Thallow Barrow Den.\n\nProvided item:", completion = "We're bringing out the bug spray, eh? I guess it can't be helped.", sourceObjectiveStatus = "unverified-source-field" }
quests[28707] = { id = 28707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spray it Again", description = "I'm gonna start setting this up.\n\nNext one goes to Marcy, further down the den. Head down this corridor here and look for her in the next main chamber.", sourceObjective = "Bring the Box of Bugkill Fumigators to Marcy Curtainfire inside the Ban'Thallow Barrow Den.", progress = "Wasn't expecting to see a stranger down here!", completion = "Fumigators? From Rinno? Geez...", sourceObjectiveStatus = "unverified-source-field" }
quests[28708] = { id = 28708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Outland!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Commander Duron in Hellfire Peninsula.\n\nThe expeditionary forces require your help to overcome the demonic armies of the Burning Legion! Use the portal on the middle level of the tower in the Mage District to travel to the Blasted Lands, then travel through the Dark Portal to reach the Stair of Destiny in Outland.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Commander Duron at the Stair of Destiny in Hellfire Peninsula.", completion = "The expedition needs your help, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28709] = { id = 28709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Northrend!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Recruitment Officer Blythe at Valiance Keep in Borean Tundra.\n\nThe Valiance Expedition needs your help to keep the forces of the Scourge under control and safeguard civilized lands! Make your way to the Stormwind Docks and take the ship north to Valiance Keep.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Recruitment Officer Blythe at Valiance Keep in Borean Tundra.", completion = "The expedition needs your help, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28710] = { id = 28710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spray it One More Time", description = "You'd think Rinno could have sent more than a single {race} down here to give us a hand! That freeloader...\n\nI'm gonna set this up. Head north from this room through the corridor and look for Sana. She's probably gotten herself lost in the last chamber, so check the side passages once you get there.", sourceObjective = "Bring the Box of Bugkill Fumigators to Sana Curtainfire in the Ban'Thallow Barrow Den.", progress = "What're you doing here?", completion = "Rinno sent you! And you brought... fumigators? Ugh!", sourceObjectiveStatus = "unverified-source-field" }
quests[28711] = { id = 28711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Northrend!", description = "All able bodied members of the Horde are hereby ordered to report to the Warsong Recruitment Officer at Warsong Hold.\n\nThe Warsong Offensive needs your help to overcome the continued threat from the undead Scourge.\n\nTake the zeppelin to Warsong Hold from Orgrimmar's western zeppelin tower and present yourself to the recruitment officer.\n\nDestiny calls!", sourceObjective = "Report to the Warsong Recruitment Officer at Warsong Hold in Borean Tundra.", completion = "The Warsong Offensive could use more like you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28712] = { id = 28712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enter the Dragon Queen", description = "Hello, {race}. I wish we could meet in more favorable circumstances. The world hangs by a thread, and all that the Titans have wrought may be in jeopardy.\n\nIt saddens me greatly, but my judgment is final. Deathwing - the horrific creature that was once the Earth Warder and once my friend - must be destroyed.\n\nI have prepared a site atop the Highlands, to the west of the Vermillion Redoubt, where I can bring about his end. Seek out the Circle of Life and speak with Lirastrasza within. I will join you there.", sourceObjective = "Seek out Lirastrasza at the Circle of Life in Twilight Highlands.", completion = "Hello again, {race}. I hear you were instrumental in our push toward Grim Batol - thank you!\n\nAlexstrasza has sanctified this ground in the hopes of luring Deathwing here. She'll perform a ceremony to lure him out... and then destroy him within this sacred circle.\n\nLet's hope her plan works.", sourceObjectiveStatus = "unverified-source-field" }
quests[28713] = { id = 28713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Balance of Nature", description = "Greetings, {name}. I am Ilthalaine. My purpose in Shadowglen is to train young {class}s like you and to ensure that the balance of nature is maintained.\n\nThe spring rains were particularly heavy this year, causing some of the forest's beasts to flourish while others suffered. Unfortunately, the nightsaber numbers grew too large, and they will devastate the other populations if they are not culled.\n\nJourney forth, young {class}, and thin saber populations so that nature's harmony will be preserved.", sourceObjective = "Kill 6 Young Nightsabers.", progress = "There is still work to be done, {name}. Return to me once you have thinned the nightsaber population.", completion = "You performed your duties well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28714] = { id = 28714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Moss Corruption", description = "You seem to know what you're doing. Perhaps I can task you with something a little more important.\n\nAs you may well know, the corruption in Teldrassil was supposedly wiped away. Yet something lingers. The creatures have not calmed and all manner of problems still plague us.\n\nI need you to deal with the grellkin that have gathered to the west, and while you're there, I want you to search them for fel moss. This will help me determine from where this continuing corruption stems.", sourceObjective = "Collect 6 Fel Moss from the grellkin to the west of Ilthalaine.", progress = "Satisfy my suspicions, {name}. Bring to me fel moss from the grellkin.", completion = "Your service to the creatures of Shadowglen is worthy of reward, {name}.\n\nYou confirmed my fears, however. The grellkin are still tainted by fel moss, despite Teldrassil's blessing. Something sinister remains within the tree. I can only hope that the Gnarlpine tribe of furbolgs are free of the corruption, or we are still in grave danger.\n\nI will look into this further and contact those who might be of aid. Thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28715] = { id = 28715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonic Thieves", description = "Vicious little grell! They've been stealing from our foodstores again.\n\nIf you wouldn't mind lending a hand, they are sure to have my stolen bags within their camps to the west. I would be glad to reward you if you can bring them back to me.", sourceObjective = "Recover Melithar's Stolen Bags near the grellkin to the west.", progress = "I don't have any spare supplies for my customers until my stolen goods are recovered. Have you had any luck?", completion = "Elune be praised! And you as well, young {class}.\n\nThere are many young night elves in need of these, but I'd be more than happy to give you one of the bags as a reward. I'm sure it will come in handy.\n\nSafe travels to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28716] = { id = 28716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Twilight Highlands!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to the throne room in Stormwind Keep.\n\nKing Wrynn requires a trustworthy and proven hero for a mission of the utmost importance.\n\nStormwind Keep can be found in the eastern portion of Stormwind City.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Speak with King Varian Wrynn at Stormwind Keep in Stormwind.", completion = "We are pleased that you have answered our summons, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28717] = { id = 28717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Twilight Highlands!", description = "All able-bodied members of the Horde are hereby ordered to report to Garrosh Hellscream in Grommash Hold.\n\nThe Warchief requires your help to prepare for the glorious assault on the Twilight Highlands and our dual enemies, the Alliance and Twilight's Hammer.\n\nMeet with the Warchief in Grommash Hold at the center of Orgrimmar's Valley of Strength.\n\nDestiny calls!", sourceObjective = "Report to Garrosh Hellscream at Grommash Hold in Orgrimmar.", completion = "Soon, the assault on the Twilight Highlands will begin, and I intend for you to be a part of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[28718] = { id = 28718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where There's Smoke, There's Delicious Meat", description = "Say there, {class}... do you like meat?  Even better, do you like money?\n\nI got a second cousin who's making a killing in the frozen meats business.  He's set up a smoking pit up north, and he's looking for help hunting all the dangerous beasties that always tend to taste so good.\n\nCarnivores pay well, friend.  I'm too heavily invested here in this barrow den - what was I thinking? - so I might as well pass the tip on to a helpful {race} like yourself.\n\nHis name's Jez.  Head northeast, and look for the smoke!", sourceObjective = "Find Jez Goodgrub at Goodgrub Smoking Pit in Winterspring.", completion = "Look around you; you're looking at the largest goblin-owned hunting reserve in Kalimdor! I've got the licenses to shoot and eat everything that walks on the snow from here to Everlook... and lemme tell you, they're good eatin'!", sourceObjectiveStatus = "unverified-source-field" }
quests[28719] = { id = 28719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Gamy", description = "Many find the meat of the Shardtooth bears to be too gamy for their taste. I disagree, though I'm not one to judge the tastes of others.\n\nThe Shardtooth Maulers, however - their brown-furred cousins, to the south - have much more tender flesh, particularly in their paws. And I've heard that the snout is also considered a delicacy.\n\nContinue your hunt, {name}. Let's see if you can bag those maulers for ol' Francis.", sourceObjective = "Kill 15 Shardtooth Maulers.", sourceObjectiveStatus = "unverified-source-field" }
quests[28722] = { id = 28722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yetiphobia", description = "It's all ready, {name}!\n\nNow, I told my friend Legacki that I have a surprise for her. This is where you come in!\n\nI'm going to give you my mechanical yeti, and you'll get the honor of using it to surprise her. She's just on the other side of Everlook, near the inn.\n\nGo up to her and turn the yeti on... I'll be watching from here!", sourceObjective = "Scare Legacki with Umi's Mechanical Yeti.", progress = "She'll never expect it!", completion = "Hah! She'll think twice before making fun of my ideas again!\n\nThanks for your help, {name}. I couldn't have had so much fun without you!", sourceObjectiveStatus = "unverified-source-field" }
quests[28723] = { id = 28723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priestess of the Moon", description = "Now that you're practiced in your new ability, perhaps you'd be willing to aid us in further pursuing the corruption haunting Shadowglen.\n\nDentaria Silverglade, Priestess of the Moon, has offered to aid us. You should find her between the two pools just north of our great tree. Circle around the tree to reach her and offer her any help that you can, young {class}.", sourceObjective = "Speak to Dentaria Silverglade between the two pools in the center of Shadowglen.", completion = "It is good that you've come. It seems your training progresses quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[28724] = { id = 28724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iverron's Antidote", description = "Our friend Iverron has fallen to poison from the nearby webwood spiders. I can tend to him to keep his state from deteriorating, but I need someone to gather an ingredient to prepare him an antidote.\n\nAll around the ponds you should find Moonpetal Lilies. These flowers have great healing properties, and I can use them with the ingredients I already have to restore Iverron to better health.\n\nWould you gather them for me?  There should be many just in sight of here, near the water's edge.", sourceObjective = "Collect 7 Moonpetal Lilies.", progress = "Our dear friend is not doing well, even with my mending. Have you brought the supplies I require?", completion = "These will do perfectly. Thank you, {name}. Your swiftness is appreciated.", sourceObjectiveStatus = "unverified-source-field" }
quests[28725] = { id = 28725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Woodland Protector", description = "I must ask something more dangerous of you. Strange news has traveled to me through the whisperings of the forest spirits. The mysterious woodland protector, Tarindrella, has returned to Shadowglen again.\n\nThe dryad's presence has not been felt in the forests since before the blessing of Teldrassil. Something is surely amiss if she has journeyed back to this land.\n\nSeek out Tarindrella in the Shadowthread cave to the north. It is dangerous, but we will be prepared with this antidote just in case.", sourceObjective = "Seek out the dryad known as Tarindrella within the Shadowthread Cave at the northern end of Shadowglen.", completion = "I see you found me, young {race}.  Dentaria was wise to have sent you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28726] = { id = 28726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Webwood Corruption", description = "I'd hoped to never return to Teldrassil for such grim business. I'd hoped that its corruption had been wiped away completely.  Something foul lingers.\n\nThese spiders suffer much more deeply from the corruption than the other nearby wildlife. They are becoming a danger to your people and a danger to the forest. We must thin their numbers, but more importantly, we need to find the source of the corruption that plagues them.\n\nI will come with you and aid you in this.", sourceObjective = "Kill 12 Webwood Spiders.", progress = "This is grim work. It pains me to have to inflict such violence on creature of the forest, corrupt or not.", completion = "This corruption these spiders suffer from is not simply surface deep. It cannot be magic or subtle malintent. It is bred into them.\n\nIt seems our next task is clear.", sourceObjectiveStatus = "unverified-source-field" }
quests[28727] = { id = 28727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Touch", description = "If these spiders are born with corruption in their veins, then their broodmother must be at the root of this evil.\n\nLet us make our way to the far north end of the cave and seek out Githyiss the Vile. The answers we seek lie with her.", sourceObjective = "Kill Githyiss the Vile at the northen end of the Shadowthread Cave.", progress = "I adore these forests. I want to see the corruption purged from them completely. When next I return, I want to do so with a lighter heart.", completion = "Githyiss and her brood were being corrupted by this totem. This is a furbolg totem.\n\nThis is very troubling indeed. This means the Gnarlpine are still a danger to these forests. We let our guard down too soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[28728] = { id = 28728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Things to Come", description = "I will pursue the trail of the Gnarlpine and track this corruption to its source. If you ever encounter Athridas Bearmantle in Dolanaar, he knows intimately of the problems that plague this forest, and he can direct you on how to help further.\n\nI'm sure we will meet again with time. Perhaps you can aid me in dealing with the source of this corruption once I locate it. For now, I will take you back to Dentaria so that you may finish your training. Thank you for all that you have done, {name}.", sourceObjective = "Speak to Dentaria Silverglade between the pools in northern Shadowglen.", completion = "You've returned! It's good to see you. It seems you've dealt with the source of much of the corruption in Shadowglen.\n\nTeldrassil still suffers and will need attention, but we can afford a moment or two for you to finish your training here in Shadowglen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28729] = { id = 28729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Crown of Azeroth", description = "As part of a ritual to complete your training here in Shadowglen, you must learn about our recent history.\n\nThere is a task you must perform. Go to the moonwell to our northeast and retrieve a phial of its water. While there, you will witness a glimpse of our magics and learn of our past.\n\nWhen you are done there, bring the water back to me, and I will direct you further.", sourceObjective = "Fill the Crystal Phial at the moonwell in northeast Shadowglen.", progress = "Our recent history is fraught with strife and violence. There is still much with which we must come to terms.", completion = "Well done, {name}. You have one task left for you before you depart Shadowglen for the open wilds of Teldrassil.", sourceObjectiveStatus = "unverified-source-field" }
quests[28730] = { id = 28730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Waters", description = "Tenaron Stormgrip oversees all that happens in this glade. He presides at the top of Aldrassil.\n\nIf you look to your south, you will see the underside of the ramp that leads up to him. Ascend this ramp and complete your training.\n\nIt was wonderful to have met you, {name}. I swell with pride knowing that among young night elves, there are some so selfless and full of life as you are. You will do great things for our people. You will do great things for this world.\n\nUntil we meet again.", sourceObjective = "Bring the filled crystal phial to Tenaron Stormgrip at the top of Aldrassil in Shadowglen.", progress = "The moonwells hold the waters of the Well of Eternity, the ancient source of magic that has wrought so many horrors upon our world.\n\nThe druids take advantage of its properties, the Sentinels revere the wells as shrines to Elune, and now even the returning Highborne look to the wells longingly.", completion = "So you have heard the first part of the aftermath of the Battle of Mount Hyjal. There is much more for you to learn and the task you have begun here will continue through the rest of your journey through Teldrassil and into Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[28731] = { id = 28731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Passing Awareness", description = "While there is more I could speak to you of the moonwells and of Teldrassil, I must send you along. Corithras Moonrage will be expecting you. I have poured the phial of water you brought to me into this vessel to bring to him.\n\nSeek out Corithras. You will find him at the moonwell in Dolanaar. Follow the road south from Aldrassil out of Shadowglen, and continue to follow the cobblestones as the road turns west.\n\nMind you stay on the road though, {name}. There are dangerous beasts in the forests of late.", sourceObjective = "Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar.", progress = "Greetings, {class}. For what purpose do I owe the pleasure of our meeting?", completion = "Ah, I see. You were sent by Tenaron. Well then, it would seem we have much to talk about, much to do.\n\nBefore we get to the task at hand, you should take in the lesson of this moonwell.", sourceObjectiveStatus = "unverified-source-field" }
quests[28732] = { id = 28732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Can Only Mean One Thing...", description = "Raz and I were enlisted by the Guardians of Hyjal to investigate the re-emergence of Ragnaros into our world. Let me go ahead and confirm that he is back and he is angry! We also have evidence that these Twilight's Hammer cultists are moving elementals from here to Blackrock Caverns, over in the Eastern Kingdoms.\n\nRaz and I were about to head over there to investigate. We've got room for another in the mole machine if you're interested. Just meet us on the inside and we'll begin our journey.", sourceObjective = "Take Pip's Mole Machine to Blackrock Mountain.", progress = "HELP! HELP!", completion = "Oh dear, Raz has been captured! As soon as we entered a dozen cultists and some big fat ogre jumped us. I ran while Raz tried to fight them off. We need to save him, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28733] = { id = 28733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Botany", description = "HELP! HELP! Crazed undead are attacking my farm! That psycho warden over at the Sludge Fields is probably responsible for this mess. Help me fight off the zombies!", sourceObjective = "Survive a Massive Wave of Zombies.", completion = "PHEW! That was close! You're a real natural with these plants, {class}. You know, I brought the seeds here with me from Lost Isles. I figure once I get them all figured out I'll make a fortune in the deadly flower business!\n\nWha... LOOK! MORE ARE COMING!", sourceObjectiveStatus = "unverified-source-field" }
quests[28734] = { id = 28734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favor for Melithar", description = "You should speak with Melithar. I believe he had some troubles with the grell already.\n\nI expect he can offer you a well needed place to store more of your goods should you aid him.", sourceObjective = "Speak to Melithar Staghelm in Shadowglen.", completion = "Ilthalaine sent you? He was wise to do so. I am indeed in need of help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28735] = { id = 28735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Chamber of Incineration!", description = "It was an ambush, {name}! As soon as we walked in a super-fat ogre named Rom'ogg Bonecrusher attacked us! Raz bravely defended me while I ran off to hide. I watched as they beat him unconscious and then dragged him to a place the fat one called the \"Chamber of Incineration.\" I think it's just down the hall across the bridge.\n\nI'm too scared to go any further. Take my all-purpose diving helm and search for Raz. I'll communicate with you through the helm.\n\nAnd if you find that ogre, kill him!", sourceObjective = "Kill Rom'ogg Bonecrusher.", progress = "<Finkle's helm crackles with static.>", completion = "<Pip's helm crackles with static.>\n\nRAZ! What have they done to him!? FOLLOW HIM!", sourceObjectiveStatus = "unverified-source-field" }
quests[28736] = { id = 28736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire From the Sky", description = "The remnants of Schnottz's organization persist here on the Maker's Ascent, making the region deadly to any who draw near.\n\nThere's plenty of ammunition, but without a good spotter, I'm just firing blind.\n\nHop in and give me a hand here. Those soldiers won't know what hit them!", sourceObjective = "Board the Confiscated Artillery and use it to kill 100 Schnottz Infantrymen.", progress = "It's a target-rich environment, {class}.", completion = "The enemy on Maker's Ascent remain a threat, but with your help we've dealt a serious blow to their numbers and their morale.", sourceObjectiveStatus = "unverified-source-field" }
quests[28737] = { id = 28737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Is This Place?", description = "<Pip's helm gives you a slight jolt.>\n\nWhat is this place? It looks like they're doing something terrible to that nether dragon. The energy is being siphoned from the creature into that lady! We need to stop this ritual!\n\nKill Corla to get past this hall!", sourceObjective = "Kill Corla, Herald of Twilight.", progress = "<Finkle's helm crackles with static.>", completion = "<Pip's helm crackles with static.>\n\nWe haven't got much time. Raz looked injured. If we get to him in time there might be a chance that I can turn him back into a regular orc!\n\n<You feel a sharp pain in the back of your head and hear the jingling of coins.>\n\nSorry about that. I figured I'd send through some gold - for your troubles and all that...", sourceObjectiveStatus = "unverified-source-field" }
quests[28738] = { id = 28738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Forge", description = "<Pip's helm hums with energy.>\n\nDamn it! Raz won't stop! It's as if he were possessed with a burning vengeance for all things Twilight! It looks like if we're going to get past this room and catch up with Raz we'll need to take out the Twilight armorer, Karsh Steelbender. Kill him quick, {name}.", sourceObjective = "Kill Karsh Steelbender.", progress = "<Pip's helm crackles with static.>", completion = "<Pip's helm crackles with static.>\n\nThat should put a stop to their armory - at least for now.\n\nRaz ran off across the ramp on the other side of the forge. GO GO GO!", sourceObjectiveStatus = "unverified-source-field" }
quests[28740] = { id = 28740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do My Eyes Deceive Me?", description = "<Pip's helm explodes with the sound of a loud girlish scream.>\n\nIT CAN'T BE! I... I was stuck inside one of those beasts for the better part of a month. Yes, literally stuck inside its stomach. If it weren't for my suit and the all-purpose helm I'd have died a fiery death! And look at that, it's had a litter of pups!\n\nY... You gotta stop that thing, {name}! We can't let it or its pups make it out of here alive!", sourceObjective = "Kill Beauty.", progress = "<Finkle's helm crackles with static.>", completion = "<Pip's helm crackles with static.>\n\nPhew... That's one less thing I'll need to worry about if we ever make it out of this place.", sourceObjectiveStatus = "unverified-source-field" }
quests[28741] = { id = 28741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascendant Lord Obsidius", description = "<Pip's helm buzzes.>\n\nGOOD GOLLY! Look at this place! A... Are those Deathwing's claw marks on the ceiling?! And what's that creature in the center of the chamber?\n\nI don't see Raz anywhere. Let's take care of this monster and find Raz!", sourceObjective = "Kill Ascendant Lord Obsidius.", progress = "<Finkle's helm crackles with static.>", completion = "Poor Raz. He was the best friend a gnome ever had. At least we avenged his death and cleared out this hellish cavern!", sourceObjectiveStatus = "unverified-source-field" }
quests[28742] = { id = 28742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shy-Rotam", description = "Time for the big kill, pal! Shy-Rotam lurks in the north, the largest frostsaber of them all.\n\nYou should feel honored. There's no fiercer game for a hunter to match their skills against... and if you saw the cash I'm being offered by gourmands that want a piece of this fellow, your eyes would pop out!\n\nOnce you've got her, head on back to camp. Don't want to totally exhaust our frostsaber population in one day...", sourceObjective = "Slay Shy-Rotam.", completion = "Amazing, kid. You're a cut above! I went through about five different contracted hunters trying to get that cat.\n\nWell, we found two of them after the Captain got the corpse, but let's not dwell on that...", sourceObjectiveStatus = "unverified-source-field" }
quests[28743] = { id = 28743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tailgunner!", description = "You up for a little hunting, {name}?\n\nHop in! I'll fly, you shoot!", sourceObjective = "Shoot down 15 Schnottz Aces.", sourceObjectiveStatus = "unverified-source-field" }
quests[28744] = { id = 28744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghouls Hate My Grains", description = "You're a pro at this, {name}! A regular junior botanist! Listen, I've got a new seed to try called the rocknut. Use it to block the undead. Just drop it down and they'll stop dead in their tracks. Undead are so stupid!\n\nLet's give it a try!", sourceObjective = "Survive 2 Massive Waves of Zombies.", completion = "I think that made Stillwater angry. He's sending the heavy-hitters after us now. No time to lose, friend, let's go!", sourceObjectiveStatus = "unverified-source-field" }
quests[28745] = { id = 28745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Screechy Keen", description = "Them smaller owls are sure tasty, but Goodgrub says there's even bigger ones further south. Screechers, the folk around here call 'em... they make a heck of a noise when you tussle with them!\n\nBut he says they're the best owls he's ever tasted or sold, and I believe him. Why don't you go rustle up some of those for us while I keep arguin' with Francis here?", sourceObjective = "Slay 15 Winterspring Screechers.", sourceObjectiveStatus = "unverified-source-field" }
quests[28746] = { id = 28746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Penetrating Their Defenses", description = "Here we go, {name}!\n\nJust beyond that door lies the control room.\n\nI'll just run in, disable the reorigination mechanism, and then we all go home. Nice an' easy.\n\nYe see, <lad/lass>, it's this level of preparation that separates yer true archaeologist from yer average treasure hunter.\n\nNo sense in stirring up the beasties if ye don't have to. Just makes a mess a' things...", sourceObjective = "Gain entry to the Titan Control Room.", progress = "What is it, {name}?", completion = "Well, I've got bad news and I've got...\n\nNo, scratch that. There only be bad news.", sourceObjectiveStatus = "unverified-source-field" }
quests[28747] = { id = 28747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone Setup the Pumpkin Bomb", description = "You ever seen one of these?\n\n<Brazie pulls out a pumpkin.>\n\nThis ain't no ordinary pumpkin, friend. See, once you plant it they'll lay in wait until a zombie shows up and then KABLOOEY! Zombie guts all over the place. Let's go!", sourceObjective = "Survive 2 Massive Waves of Zombies.", completion = "D... Do you hear that rumblin'? I think Stillwater is comin'! HOLY MOLY LOOK OUT!", sourceObjectiveStatus = "unverified-source-field" }
quests[28748] = { id = 28748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lawn of the Dead", description = "IT'S STILLWATER! HE'S ALMOST HERE! It's going to take everything that we've got to beat him! Let's do this!", sourceObjective = "Defeat Warden Stillwater.", completion = "I can't believe we defeated him, {name}! That was the toughest fight yet, but there are still hundreds of crazed zombies roaming around Hillsbrad. We'll need to stay alert.", sourceObjectiveStatus = "unverified-source-field" }
quests[28749] = { id = 28749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "We just received a gryphon from the plaguelands, bearing news.  It doesn't sound good.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  King Wrynn has rolled the dice and sent a death knight to lead the charge for his cause, but I'm sure he can use all the help he can get.\n\nThey specifically asked for an Alliance {class} to participate in some specialized missions.  If you accept the charge, speak to me again and I will prepare a portal.", sourceObjective = "Speak with War-Mage Erallier to be teleported to Andorhal in Western Plaguelands. Then report to Thassarian within Andorhal.", completion = "It's about time you arrived, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28750] = { id = 28750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "We just received a windrider from the plaguelands, bearing news.  It doesn't sound good.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  It sounds like Sylvanas has made her move, and to make matters interesting, she's put Koltira Deathweaver, the death knight, in command.\n\nThey specifically asked for a Horde {class} to participate in some specialized missions.  If you accept the charge, speak to me again and I will prepare a portal.", sourceObjective = "Speak with Arcanist Arman to be teleported to Andorhal, in the Western Plaguelands. Then report to Koltira Deathweaver within Andorhal.", completion = "It's about time you arrived, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28751] = { id = 28751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tending the Garden", description = "Even though we beat Warden Stillwater, his zombies still roam the countryside. Look there, another wave is approaching! Help me fight them off, old buddy! Let's go!", sourceObjective = "Survive 2 Massive Waves of Zombies.", sourceObjectiveStatus = "unverified-source-field" }
quests[28752] = { id = 28752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unstoppable Onslaught", description = "See how long you can last! Hold off at least 10 waves and I'll give you some coin." }
quests[28753] = { id = 28753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doing it the Hard Way", description = "Blast it all!\n\nSomeone's gone and corrupted the entire system! There be no way fer me ta access the main repository from this console.\n\nWe're gunna hafta do this the hard way, <lad/lass>. I hope you an' yer friends here are up to a fight.\n\nThere be four guardians on the upper level of this place. I won't be able ta utilize these discs 'til they be... uhh, offline, shall we say.", sourceObjective = "Brann Bronzebeard wants you to kill Isiset, Ammunae, Setesh, and Rajh.", completion = "Arrite, then.\n\nLet's deposit these discs and be done with this!", sourceObjectiveStatus = "unverified-source-field" }
quests[28755] = { id = 28755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Annals of the Silver Hand", description = "Do you know who the Knights of the Silver Hand were? They were the original paladins of the Light, and from their ranks came knights who would later join the Argent Dawn or the Scarlet Crusade. Though many have gone astray, they still possess valuable relics of the Silver Hand.\n\nDeep in Stratholme, under the watchful eye of Instructor Galford, volumes of the Annals of the Silver Hand survive. Any volumes you could recover would be a fitting addition to the rededicated Light's Hope Chapel.", sourceObjective = "Recover a lost volume of the Annals of the Silver Hand from Stratholme.", progress = "Have you recovered any of the lost histories of the Silver Hand?", completion = "This is indeed one of the lost volumes! Tyrosus will be most pleased when he learns of your find.", sourceObjectiveStatus = "unverified-source-field" }
quests[28756] = { id = 28756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrations of Bone", description = "In life, my brothers and I fought against all the forces of the Scourge, but none were so reviled as the necromancers. It was not enough for them raise our dead comrades and send them against us; no, they created twisted golems of bone with scythes for hands.\n\nThese aberrations slew many of my brothers, and yet we could not destroy them all. I ask you, {name}, to carry on the task of the fallen. Venture into the Ossuary of Scholomance and slay the largest and most dangerous of these abominable creatures.", sourceObjective = "Kill Rattlegore in the Ossuary of Scholomance.", completion = "Your deeds do honor to those who fell in battle defending this hallowed ground.", sourceObjectiveStatus = "unverified-source-field" }
quests[28757] = { id = 28757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", sourceObjective = "Kill 6 Blackrock Battle Worgs.", completion = "You've bought us a little time, {name}, but we've got even bigger problems to deal with now.", sourceObjectiveStatus = "unverified-source-field" }
quests[28758] = { id = 28758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Life and Death", description = "Alexstrasza and Deathwing have taken into the skies over Grim Batol! Her plan unravels - the Dragon Queen is outside the Circle of Life she prepared earlier. We'll need to support her with everything we've got.\n\nHurry! Climb aboard one of the Vermillion Vanguard behind me.\n\nIf we find any Twilight Drakes aiding Deathwing, we will need to kill them off. Mount up, quickly!", sourceObjective = "Mount a Vermillion Vanguard. Slay 8 Twilight Shadowdrakes.", progress = "The battle continues, {name}.", completion = "Thanks to your quick action, the Dragon Queen still lives. She is being brought back to Wyrmrest to recover.\n\nBut the battle wasn't a complete failure. Deathwing was gravely wounded. I suspect he will go into hiding to recuperate. Alexstrasza has bought us time to strike!", sourceObjectiveStatus = "unverified-source-field" }
quests[28759] = { id = 28759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", sourceObjective = "Kill 8 Blackrock Spies.", completion = "Excellent work, {name}. You've turned out to be quite an asset to this garrison. It's time for you to train!", sourceObjectiveStatus = "unverified-source-field" }
quests[28760] = { id = 28760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for Orsis", description = "The great city of Orsis was attacked by the armies of air.\n\nWe were taken prisoner.  We were the lucky ones.\n\nMost died, trapped beneath the choking desert sands.\n\nAsaad, Al'Akir's caliph, ordered the attack... and he must pay with his life.", sourceObjective = "Slay Asaad.", progress = "Is it done, {name}?", completion = "Blessings upon you.  Please accept this as a token of my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[28762] = { id = 28762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", sourceObjective = "Kill 6 Blackrock Battle Worgs.", completion = "You've bought us a little time, {name}, but we've got even bigger problems to deal with now.", sourceObjectiveStatus = "unverified-source-field" }
