quests[28768] = { id = 28768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterspring!", description = "Donova Snowden, dwarf woman, is friend of the Timbermaw.\n\nWe trade firewater.\n\nShe is at Frostfire Hotsprings, to the east, through our cave.\n\nShe needs help to beat up the Winterfall furbolg.  Maybe you will help her.", sourceObjective = "Report to Donova Snowden at Frostfire Hot Springs in Winterspring.", completion = "Thank goodness you're here. I've discovered the secret of the fierce Winterfall furbolg.", sourceObjectiveStatus = "unverified-source-field" }
quests[28769] = { id = 28769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", sourceObjective = "Kill 8 Blackrock Spies.", completion = "Excellent work, {name}. You've turned out to be quite an asset to this garrison. It's time for you to train!", sourceObjectiveStatus = "unverified-source-field" }
