quests[28778] = { id = 28778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Boar Figurine", description = "This badly broken figurine was discarded by its last owner.  However, with the right materials and your skill in jewelcrafting, it could be completely restored.", sourceObjective = "Repair the broken figurine utilizing your skill and materials.", sourceObjectiveStatus = "unverified-source-field" }
quests[28779] = { id = 28779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Long Way from Home", description = "I've a feeling I was able to escape my captors because, frankly, there is nowhere to go.\n\nStranded on these platforms, they are bound to find me sooner or later.  Unless...\n\nIt is said that the heart of an elemental noble can grant whoever holds it the characteristics of that element.  Which, in the case of air, would be most useful during a downward trip.\n\nBring me Grand Vizier Ertan's heart so I can use its magic to land safely on the shoreline of Uldum.", sourceObjective = "Obtain Grand Vizier Ertan's Heart.", progress = "You'd best not suggest I ride with you on... whatever that thing is you flew in on.", completion = "I thank you, {name}.  Even after I had escaped, I did not imagine I'd be able to return home.", sourceObjectiveStatus = "unverified-source-field" }
quests[28780] = { id = 28780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Join the Battle!", description = "While you were out training I received an urgent message from Sergeant Willem. Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, {name}!\n\nFind Sergeant Willem north of the abbey at the command tent. Go!", sourceObjective = "Report to Sergeant Willem behind Northshire Abbey in Elwynn Forest.", completion = "It's true, we were ambushed. I don't dare send any more soldiers out there and risk losing them too. I need a volunteer. Someone willing to risk their life!", sourceObjectiveStatus = "unverified-source-field" }
quests[28781] = { id = 28781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Targets of Opportunity", description = "We were part of a clandestine operation put together by Prince Nadun of Ramkahen.  We lost most of our unit during an ambush and we're now unable to finish our mission.\n\nShould you be up for it, I can arrange for a sizable reward for you.\n\nWe were instructed to take out any targets of opportunity that would damage the enemy's military infrastructure.\n\nWe've spotted General Husam and two of his captains up ahead.  Slaying them for us will be a great favor for Ramkahen.", sourceObjective = "Slay General Husam and 2 Oathsworn Captains.", progress = "Is it done, {name}?", completion = "Excellent work, {name}.  Your reputation is well-deserved.", sourceObjectiveStatus = "unverified-source-field" }
quests[28782] = { id = 28782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bird of Legend", description = "Local legend tells of a mighty owl that circles the mountaintops like death on wings.  They named her Deathwing.\n\nSoon afterwards, they were told that that name was already taken.  So they settled on a moniker that evoked a similar sense of horror and dread:\n\nHell-Hoot.\n\nHell-Hoot can be found atop the mountain to the southwest of our smoking pit.  Silence the infernal nocturnal... so we can eat her!", sourceObjective = "Slay Hell-Hoot.", completion = "Hell-Hoot is slain, and her meat is just as succulent as you'd expect.\n\nToday, we eat a legend.  Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28783] = { id = 28783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Source of Their Power", description = "We managed to do extensive scouting before our crew was ambushed.\n\nWe discovered that Deathwing's envoy, Siamat, is giving the Neferset their newfound power.\n\nThey claim it has restored them to the greatness of old, but something else has happened.  Their very souls have been corrupted.\n\nAs one of the four winds, Siamat is incredibly powerful.  But that power has been drained considerably by this process.\n\nStrike now, while it is possible for you to slay him and bring an end to this madness.", sourceObjective = "Slay Siamat.", progress = "You're back, {name}..  What news do you bring?", completion = "It is true, then?  The great blight upon our race will soon end now that the Neferset have lost the ability to corrupt any more of our people.\n\nName your reward, {class}.  It is the least we can do for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28784] = { id = 28784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Join the Battle!", description = "While you were out training I received an urgent message from Sergeant Willem. Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, {name}!\n\nFind Sergeant Willem north of the abbey at the command tent. Go!", sourceObjective = "Report to Sergeant Willem behind Northshire Abbey in Elwynn Forest.", completion = "It's true, we were ambushed. I don't dare send any more soldiers out there and risk losing them too. I need a volunteer. Someone willing to risk their life!", sourceObjectiveStatus = "unverified-source-field" }
