quests[28789] = { id = 28789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Join the Battle!", description = "While you were out training I received an urgent message from Sergeant Willem. Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, {name}!\n\nFind Sergeant Willem north of the abbey at the command tent. Go!", sourceObjective = "Report to Sergeant Willem behind Northshire Abbey in Elwynn Forest.", completion = "It's true, we were ambushed. I don't dare send any more soldiers out there and risk losing them too. I need a volunteer. Someone willing to risk their life!", sourceObjectiveStatus = "unverified-source-field" }
quests[28790] = { id = 28790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal Summons", description = "<An unfamiliar feeling wells up from deep within you, flooding your mind with thoughts and images.>\n\nHear my words, {name}.\n\nOur world finds itself in the grip of a terrible crisis.\n\nI call upon you to lend your aid in this desperate hour.\n\nI am Krogar.\n\nSeek me out at once, and your destiny shall be revealed.\n\nYou can find me north of the Drag in Orgrimmar.", sourceObjective = "Farseer Krogar wants you to meet him in Orgrimmar.", completion = "May your sense of honor and duty serve Azeroth well, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28791] = { id = 28791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Sent Assassins", description = "Have you ever seen a goblin, {name}? They're wretched little green-skinned monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", sourceObjective = "Kill 8 Goblin Assassins.", completion = "That will teach those monsters! They'll think twice before taking another mercenary job for orcs.", sourceObjectiveStatus = "unverified-source-field" }
quests[28792] = { id = 28792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Sent Assassins", description = "Have you ever seen a goblin, {name}? They're wretched little green-skinned monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", sourceObjective = "Kill 8 Goblin Assassins.", completion = "That will teach those monsters! They'll think twice before taking another mercenary job for orcs.", sourceObjectiveStatus = "unverified-source-field" }
