quests[28797] = { id = 28797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Sent Assassins", description = "Have you ever seen a goblin, {name}? They're wretched little green-skinned monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", sourceObjective = "Kill 8 Goblin Assassins.", completion = "That will teach those monsters! They'll think twice before taking another mercenary job for orcs.", sourceObjectiveStatus = "unverified-source-field" }
quests[28798] = { id = 28798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waters of Elune", progress = "You've found an unusual fountain; the water glows like moonlight and hums with soft tones.  With a Highborne Scroll, and your impressive skill in archaeology, you could decipher the fountain's purpose.", completion = "After a few moments, you are able to use the keystone and reveal the secret of the water...." }
quests[28799] = { id = 28799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might of the Earthen", progress = "At first glance, this pillar seems very plain, but your knowledge of archaeology tells you differently.  If you had a Dwarf Rune Stone, its originations could be brought to light.", completion = "Ah ha!  You knew you'd seen this level of craftsmanship before.  Now, with the final piece..." }
quests[28800] = { id = 28800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers of the Djinn", progress = "This brazier is obviously magical, but it seems impervious to your attempts to invoke its power.  If only you had a Tol'vir Heiroglyphic keystone to help decipher the engravings on the side.", completion = "It appears as if this particular brazier has trapped a minor djinn, and freeing him would certainly bring a reward.  Right?" }
quests[28801] = { id = 28801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol'vir Heiroglyphics", progress = "This gravestone marks a strange burial site - possibly from one of the original builders.  If you could use a Tol'vir Hieroglyphic keystone to understand the words, it could be an important archaeological find!", completion = "Using the keystone, you confirm the grave is from one of the original builders, and you learn important details of the mummification process." }
quests[28802] = { id = 28802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Map of the Architects", progress = "This stone obelisk is obviously some sort of layout or map, but it isn't completely readable.  Perhaps if you had a Tol'vir Hieroglyphic keystone, the markings might make more sense.", completion = "Yes... 'X' marks the spot!  This is a detailed map of the dungeon, a valuable find indeed." }
quests[28803] = { id = 28803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance of the Wildhammer", progress = "These old bones appear dwarven, possibly from the original builders of Grim Batol.  It's possible you could compare the markings on the stone belt buckle to a Dwarf Rune Stone, and discover more about this find.", completion = "After comparing the two very closely, you are sure these are the remains of the Wildhammer.  The treachery committed against them fills your heart with anger." }
quests[28804] = { id = 28804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Contingency Plan", progress = "These are definitely some sort of plans, but for what you aren't certain.  They bear distinctive markings that could be compared to a Dwarf Rune Stone.", completion = "Interesting!  It seems as if the Dark Iron dwarves had a strategic plan in the case of an elemental invasion.  As the elemental forces are ageless and unchanging, it seems as if these ancient techniques are still viable even today." }
quests[28805] = { id = 28805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of the Storm", description = "Greetings, friend.\n\nOn behalf of the Earthen Ring I thank you for answering my call.\n\nYou are known to us by name, {name}.\n\nYour exploits and accomplishments are many. Azeroth already stands in your debt, and yet again she is in need of her heroes.\n\nI am but a messenger. A familiar presence seeks audience with you.\n\nPeer into the Waters of Farseeing and behold the fate of our world.", sourceObjective = "Farseer Krogar wants you to look into the Waters of Farseeing.", progress = "Yes, {class}?", completion = "Now that your eyes have seen the truth, where will you choose to serve?", sourceObjectiveStatus = "unverified-source-field" }
quests[28806] = { id = 28806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fear No Evil", description = "Have you embraced the Holy Light yet, <brother/sister>? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers!\n\nTake this prayer book with you into the field and cast the Light's healing touch on the injured.", sourceObjective = "Revive 4 Injured Stormwind Soldiers.", progress = "Rescue our soldiers!", completion = "I think you now understand the power of the Light. The Light giveth hope, brother and the Light taketh from the darkness! BLESSED BE THE LIGHT!", sourceObjectiveStatus = "unverified-source-field" }
quests[28807] = { id = 28807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expert Opinion", description = "<Anduin holds up the matching badges.>\n\nThe medallion we found on the farm is identical to the one in Samuelson's notes! It can't be a coincidence. I think Samuelson is up to something, but we need a smoking gun before we can accuse one of my father's most trusted guards.\n\nThere's only one person I trust to sort this all out: Mathias Shaw, the director of SI:7. Show him these badges and see what he thinks. Meanwhile, I'll go back to the keep and watch Samuelson like a hawk!", sourceObjective = "Bring the Suspicious Badges to Mathias Shaw at SI:7 Headquarters in Stormwind.", progress = "What's this you've brought me?", completion = "Anduin has been investigating the Twilight's Hammer? Weren't you supposed to keep him OUT of trouble?\n\nHmmm. Let me see those badges you've discovered.", sourceObjectiveStatus = "unverified-source-field" }
quests[28808] = { id = 28808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fear No Evil", description = "Have you embraced the Holy Light yet, <brother/sister>? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers!\n\nTake this prayer book with you into the field and cast the Light's healing touch on the injured.", sourceObjective = "Revive 4 Injured Stormwind Soldiers.", progress = "Rescue our soldiers!", completion = "I think you now understand the power of the Light. The Light giveth hope, brother and the Light taketh from the darkness! BLESSED BE THE LIGHT!", sourceObjectiveStatus = "unverified-source-field" }
quests[28809] = { id = 28809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fear No Evil", description = "Have you embraced the Holy Light yet, <brother/sister>? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers!\n\nTake this prayer book with you into the field and cast the Light's healing touch on the injured.", sourceObjective = "Revive 4 Injured Stormwind Soldiers.", progress = "Rescue our soldiers!", completion = "I think you now understand the power of the Light. The Light giveth hope, brother and the Light taketh from the darkness! BLESSED BE THE LIGHT!", sourceObjectiveStatus = "unverified-source-field" }
